(window.GIM_TS=window.GIM_TS||{})["Bava Batra.4"]={"from":96,"a":[["\u0003ואחת שיחד לה בכתובתה\u0004 אף שלא כתב את הדבר בכתובה, אבל ייחד שדה זה לאחר מכן לצורך תשלום הכתובה, \u0003ואחת שהכניסה לו שום משלה\u0004 שהביאה איתה מבית אביה, וייחד הבעל שדה זה לערוב לתשלומים כ\"נכסי צאן ברזל\". ששלושה שדות אלה האשה מקפידה יותר שלא יימכרו, וגם אם נמכרו בהסכמתה אנו אומרים שלא נתרצתה, ולא היה זה אלא לעשות נחת רוח לבעלה.","ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 אלו נכסים אין אומרים בהם שמכירת הבעל בטלה? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003שאר נכסים\u0004 שלו, שמשועבדים לכתובתה, שנאמר שמכרו בטל — \u0003כל שכן דהויא ליה\u0004 \u0005[שתהיה לו]\u0006 \u0003איבה\u0004 אם לא תסכים למכירה, \u0003דאמר\u0004 \u0005[שהוא,\u0006 הבעל, \u0005אומר]\u0006 \u0003לה: עיניך נתת בגירושין ובמיתה,\u0004 שאת אינך מניחה לי למכור מפני שאת חושבת על מותי או על גירושין, ולכן יש לומר גם בהם שהמיקח בטל, אף שאינה מסכימה באמת למכר!","\u0003אלא\u0004 תאמר ששלושה שדות אלו שהוזכרו שמיקחם בטל באו \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003נכסי מלוג\u0004 נכסי האשה, שלבעל יש רשות ליהנות מפירותיהם אבל גופם שייך לאשה (אלא שאם מתה בחייו הוא יורש אותם) שאם הסכימה האשה למכירה — המכר קיים, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003אמימר: איש ואשה שמכרו בנכסי מלוג\u0004 — \u0003לא עשו ולא כלום!\u0004","ומשיבים: \u0003כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 דברי \u0003אמימר\u0004 היה זה לומר שאין כל אחד מהם לבד יכול למכור, ולכן \u0003היכא דזבין איהו ומית אתיא איהי ומפקא\u0004 \u0005[היכן שמכר הוא ומת באה היא ומוציאה]\u0006 מן הלקוחות, \u0003אי נמי זבנה איהי\u0004 \u0005[או גם כן\u0006 במקרה ש\u0005מכרה היא]\u0006 \u0003ומתה, אתא איהו ומפיק בתקנתא דרבנן\u0004 \u0005[בא הוא ומוציא על ידי תקנת חכמים],\u0006 \u0003וכ\u0004דברי \u0003ר' יוסי בר חנינא,\u0004 ש\u0003אמר ר' יוסי בר חנינא:\u0004 כשישבה הסנהדרין \u0003באושא התקינו, האשה שמכרה בנכסי מלוג ומתה\u0004 — \u0003הבעל מוציא מיד הלקוחות.\u0004","\u0003אבל היכא דזבינו תרוייהו לעלמא\u0004 \u0005[היכן שמכרו שניהם ל\u0006אדם \u0005אחר],\u0006 \u0003אי נמי זבנה איהי לדידיה\u0004 \u0005[או גם כן\u0006 אם \u0005מכרה היא לו]\u0006 — \u0003זבינה זביני\u0004 \u0005[מכרה מכר].\u0006 ובמקרה זה דייקנו מן המשנה כי אם יביא הבעל ראיה שאשתו מכרה לו מנכסי מלוג — תעמוד הקרקע בידיו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אמימר אמר כ\u0004דעת \u0003ר' אלעזר\u0004 שמי שאין בידו גם גוף הדבר וגם זכות הנאה מפירותיו — אינו יכול למכור. ואילו משנתנו היא כדעת חכמים החולקים עליו.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר את עבדו\u0004 הכנעני, \u0003ופסק עמו\u0004 המוכר עם הקונה \u0003שישמשנו\u0004 עוד \u0003שלשים יום\u0004 לאחר זמן המכר,","ואז היכה אותו למוות, \u0003ר' מאיר אומר: הראשון,\u0004 המוכר, \u0003ישנו בדין יום או יומים\u0004 שאמרה התורה שהמכה את עבדו הכנעני ולא מת העבד מיד, אלא נשאר חי יום או יומים — פטור האדון מדין מיתה (ראה שמות כא, כ–כא). וזה שמכרו נחשב אדוניו \u0003מפני שהוא\u0004 עדיין \u0003תחתיו\u0004 ומשמש אותו בפועל, \u0003והשני\u0004 שקנאו, \u0003אינו בדין יום או יומים,\u0004 אלא דינו כהורג אדם סתם, שחייב מיתה, אף אם מת העבד זמן רב אחר כך, \u0003מפני שאינו\u0004 בפועל \u0003תחתיו.\u0004","וטעמו של ר' מאיר, כי \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 שכל המחזיק בזכויות השימוש וההנאה שבדבר, נחשב כבעלים באותה שעה.","\u0003ר' יהודה אומר: השני,\u0004 הקונה, \u0003ישנו בדין יום או יומים, מפני שהוא,\u0004 העבד, \u0003כספו, הראשון אינו בדין יום או יומים\u0004 משום \u0003שאינו כספו,\u0004 ואף שהוא משתמש בו — אינו נחשב כלל כבעליו. וטעמו של ר' יהודה — \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב].\u0006","\u0003ר' יוסי אומר:\u0004"],["\u0003שניהם ישנן בדין יום או יומים, זה מפני שהוא תחתיו, וזה מפני שהוא כספו, ו\u0004מסבירים את טעמו: \u0003מספקא ליה אי\u0004 \u0005[ומסופק לו אם]\u0006 \u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003וספק נפשות להקל,\u0004 שמשום שיש ספק בדבר ניצל המכה מדין מיתה.","\u0003ר' אלעזר אומר: שניהם אינן בדין יום או יומים, זה לפי שאינו תחתיו, וזה לפי שאינו כספו.\u0004","\u0003ואמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא יקם כי כספו הוא\"\u0004 (שמות כא, כא), יש כאן הדגשה, לומר: \u0003כספו המיוחד לו,\u0004 אבל אם אינו מיוחד לו מפני שיש לאחר זכות בו — אין בו דין של יום או יומיים. והוא המקור לדברי אמימר שבעל ואשה אינם יכולים למכור בנכסי מלוג, הבעל — משום שאינם שלו, והאשה — משום שזכות השימוש בידי הבעל.","שנינו במשנה ש\u0003לא לאיש חזקה בנכסי אשתו.\u0004 ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: אשת איש צריכה למחות,\u0004 ונברר, \u0003במאן\u0004 \u0005[במי]\u0006 מדובר כאן שצריכה למחות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003באחר\u0004 אדם זר שהחזיק בנכסיה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: אין מחזיקין,\u0004 כלומר, אין דין חזקה \u0003בנכסי אשת איש\u0004 לפי שבהיותה נשואה היא סומכת על בעלה שיטפל בענייני הרכוש. \u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה שצריכה למחות \u0003בבעל,\u0004 ומכאן נלמד שלפעמים יכול הבעל (אם יש בידו טענה) להחזיק בנכסי אשתו לאחר שלוש שנים, אם אינה מוחה, והרי זה בניגוד לדברי המשנה!","\u0003אמר רבא:\u0004 \u0003לעולם\u0004 תאמר שרב אמר את דבריו \u0003בבעל\u0004 שצריכה האשה למחות בו. \u0003וכגון שחפר בה\u0004 הבעל \u0003בורות, שיחין ומערות\u0004 שלא רק אכל מפירות השדה, שבכך לבד אין ליצור חזקה לבעל בנכסי אשתו, אלא גם עשה שינויים ונזקים בגוף הקרקע, שמעשיו מוכיחים שנוהג בשדה זה כבשלו, ואם לא מחתה — יש לו חזקה.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר רבה בר אבוה: אין חזקה לנזקין!\u0004 ואנו מבינים שאדם העושה דבר שיש בו נזק לשדה חבירו — אין בכך דין חזקה, ואפילו לאחר זמן מרובה יכול למחות בו ולסלק אותו משדהו. ואף כאן, הבעל הוא בגדר מזיק בשדה, ואין לו חזקה על ידי כך!","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 והבן את הדברים באופן זה: \u0003אין דין חזקה לנזקין,\u0004 שהגורם נזק לחבירו אינו צריך להמתין שלוש שנים, אלא כיון שלא מחו בו — יש לו חזקה מיד. ולפי זה הבעל החופר בור בנכסי אשתו, ולא מחתה, קנה מיד.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לאו איתמר עלה\u0004 \u0005[האם לא\u0006 כך \u0005נאמר עליה]\u0006 על ההלכה שאין חזקה לנזקים: \u0003רב מרי אמר\u0004 שהלכה זו אמורה \u0003בקוטרא\u0004 \u0005[בעשן]\u0006 שבזה אין חזקה לעולם, \u0003רב זביד אמר: בבית הכסא,\u0004 שמפני ריחו הרע אין בו חזקה. אבל בדברים אחרים הגורמים נזקים, כגון חפירת בורות שיחין ומערות — יש חזקה, ובמקרה שכזה אמר רב שצריכה אשה למחות בבעלה, ואם לא כן — החזיק בנכסיה.","\u0003רב יוסף אמר: לעולם\u0004 הכוונה בדברי רב היא שאשה צריכה למחות \u0003באחר, וכגון שאכלה\u0004 המחזיק \u0003מקצת\u0004 זמן \u0003חזקה בחיי הבעל ושלש\u0004 שנים \u0003לאחר מיתת הבעל,\u0004 שבמקרה זה צריכה האשה למחות, שאם לא כן — תהא לאחר חזקה. וכיצד תועיל החזקה? \u0003מיגו דאי בעי אמר ליה\u0004 \u0005[מתוך שאם היה רוצה היה אומר לה]:\u0006 \u0003אנא זבינתה מינך\u0004 \u0005[אני קניתי\u0006 את השדה \u0005ממך]\u0006 לאחר מות הבעל, והרי החזקתי בו שלוש שנים, \u0003כי אמר ליה נמי\u0004 \u0005[כאשר אומר לה גם כן]:\u0006 \u0003את זבינתה ליה\u0004 \u0005[את מכרת אותה לו,\u0006 לבעל\u0005]\u0006 \u0003וזבנה ניהלי\u0004 \u0005[\u0006\u0005ו\u0006הוא \u0005מכר לי]\u0006 — \u0003מהימן\u0004 \u0005[נאמן]\u0006 על כך. ומשום כך צריכה למחות בו לאחר מיתת בעלה, כדי שלא יוכל לטעון כך.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של הדבר, \u0003אמר רב: אין מחזיקין בנכסי אשת איש.\u0004"],["\u0003ודייני גולה אמרו: מחזיקין. אמר רב: הלכה כדייני גולה. אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב: הדר ביה מר משמעתיה\u0004 \u0005[חזר בו אדוני משמועתו]\u0006 שאמר שאין מחזיקין בנכסי אשת איש? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מסתברא אמרי\u0004 \u0005[מסתבר\u0006 הדבר \u0005אמרתי]\u0006 לגבי מקרים מסויימים, שיש חזקה אף בנכסי אשת איש. שהסביר רב את הדבר, כמו שלאחר דורות הסבירו \u0003רב יוסף,\u0004 כאמור לעיל, כשהחזיק שלוש שנים לאחר מות הבעל.","שנינו במשנה: \u0003ולא לאשה\u0004 חזקה \u0003בנכסי בעלה וכו'.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאין לה חזקה, \u0003כיון דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 זכות \u0003מזוני\u0004 \u0005[\u0006ל\u0005מזונות]\u0006 מנכסי בעלה, הרי \u0003מזוני\u0004 \u0005[מזונות]\u0006 \u0003הוא דקא אכלה\u0004 \u0005[שהיא אוכלת]\u0006 ואין מכאן הוכחה לחזקת בעלות! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו במשנה אלא במקרה ש\u0003יחד לה ארעא אחריתי\u0004 \u0005[קרקע אחרת]\u0006 \u0003למזונה\u0004 ועל כך אמרה המשנה שאף שהיא אוכלת משדה שלא ייחד לה — אין לה חזקה.","ומדייקים ממה ששנינו במשנתנו: חזקה אין לאשה בנכסי בעלה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ראיה יש,\u0004 שאם הביאה ראיה בשטר שבעלה מכר לה את השדה — הרי הוא שלה. ויש לשאול: מדוע תהא זו ראיה? \u0003לימא\u0004 \u0005[נאמר]\u0006 כי \u0003לגלויי זוזי\u0004 \u0005[לגלות\u0006 את \u0005הכסף]\u0006 שיש בידה \u0003הוא דבעי\u0004 \u0005[שרוצה]!\u0006 שאם מציע לה את השדה למכירה, והיא תתרצה בדבר — יתגלה לו שיש לה כסף משלה, שלא סיפרה לו קודם על קיומו. ובאמת אינו מתכוון למכור מאומה, אלא לוקח ממנה כסף השייך לו!","האם \u0003שמעת מינה\u0004 \u0005[שומע אתה מכאן]\u0006 ש\u0003המוכר שדה לאשתו\u0004 — \u0003קנתה, ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 כי \u0003לגלויי זוזי\u0004 \u0005[לגלות\u0006 את \u0005הכסף]\u0006 שיש בידה \u0003הוא דבעי\u0004 \u0005[שרוצה]?\u0006 ודוחים: \u0003לא, אימא\u0004 \u0005[אמור]\u0006 ודייק מן המשנה: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ראיה יש,\u0004 אבל לא בשטר מכר, אלא \u0003בשטר מתנה\u0004 אם הוציאה שטר שנתן לה את השדה במתנה.","ובענין זה מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב הונא: לא הוה מר גבן באורתא בתחומא, דאמרינן מילי מעלייתא\u0004 \u0005[היה אדוני אצלנו בערב\u0006 בבית המדרש \u0005בתוך התחום, שאמרנו דברים מעולים]\u0006 ולא שמעת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003מאי מילי מעלייתא אמריתו\u0004 \u0005[מהם הדברים המעולים\u0006 ש\u0005אמרתם]?\u0006 אמר לו כך אמרתי: \u0003המוכר שדה לאשתו\u0004 — \u0003קנתה, ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 כי \u0003לגלויי זוזי\u0004 \u0005[לגלות\u0006 את \u0005הכסף]\u0006 שיש בידה \u0003הוא דבעי\u0004 \u0005[שרוצה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, ואין בכך חידוש, \u0003דל זוזי מהכא ותיקני בשטרא\u0004 \u0005[הוצא\u0006 את \u0005הכסף מכאן ותקנה בשטר]!\u0006 שגם אם לא שילמה לו הכסף (או שאין הכסף באמת שייך לה) מכל מקום יש לה קנין בשדה מחמת השטר. \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003נכסים שיש להן אחריות\u0004 (מקרקעין) \u0003נקנין בכסף\u0004 לבד \u0003ובשטר\u0004 לבד \u0003ובחזקה\u0004 לבד?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003ולאו איתמר עלה\u0004 \u0005[וכי לא נאמר עליה],\u0006 \u0003אמר שמואל: לא שנו אלא בשטר מתנה, אבל בשטר מכר\u0004 — \u0003לא קנה עד שיתן לו דמיה?\u0004 ענה לו רב הונא: \u0003ולאו מותיב\u0004 \u0005[והאם לא מקשה]\u0006 על כך \u0003רב המנונא\u0004 ממה ששנינו בברייתא: \u0003בשטר כיצד? כתב לו על הנייר או על החרס, אף על פי שאין\u0004 \u0003בו,\u0004 בנייר, \u0003שוה פרוטה: \"שדי מכורה לך\",\u0004 או \u0003\"שדי קנויה לך\"\u0004 — \u0003הרי זו מכורה ונתונה?\u0004","ענה לו רב נחמן: \u0003ולאו\u0004 \u0005[ו\u0006האם \u0005לא]\u0006 \u0003הוא\u0004 עצמו, רב המנונא, \u0003מותיב לה\u0004 \u0005[הקשה על כך]\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[תירץ זאת]\u0006 שמדובר \u0003במוכר שדהו מפני רעתה?\u0004 שהשדה היה גרוע כל כך שבאמת לא היה לו ערך והמוכר רצה להיפטר ממנו, ובמקרה כזה גומר בדעתו להקנות אף בלא לקבל את המעות לידיו, אבל במקרים אחרים — לא. ונמצא שיש חידוש בדברינו, שהמוכר שדה לאשתו — קנתה, ואין אומרים שרק לגלות את כספה רצה.","ומעירים: \u0003רב ביבי\u0004 היה \u0003מסיים בה\u0004 בפירוש ברייתא זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן,\u0004 ובלשון אחרת אמרו ש\u0003רב אשי אמר\u0004 זאת: מדוע קנה בשטר לבד? כי אנו מניחים ש\u0003במתנה בקש ליתנה לו, ולמה כתב לו בלשון מכר?\u0004 — \u0003כדי ליפות\u0004 את \u0003כחו,\u0004 שלענין אחריות עדיף שטר מכר משטר מתנה.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003לוה מן העבד ו\u0004אחר כך \u0003שחררו,\u0004 או לוה \u0003מן האשה וגרשה\u0004 — \u0003אין להן עליו כלום\u0004 ויכול שלא להחזיר להם; \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 כי \u0003לגלויי זוזי\u0004 \u0005[לגלות\u0006 את \u0005הכסף]\u0006 שיש בידם \u0003הוא דבעי\u0004 \u0005[שרצה],\u0006 ולא נתכוון ללוות באמת, אלא להוציא על ידם כסף השייך לו?","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 משום שמצטרפת לכך סברה נוספת, והיא ש\u0003לא ניחא ליה לשווייה נפשיה\u0004 \u0005[נוח לו\u0006 לאדם \u0005לעשות\u0006 את \u0005עצמו]\u0006 \u0003\"עבד לוה לאיש מלוה\"\u0004 (משלי כב, ז), ולכן מסתבר שלא רצה באמת ללוות, אלא לגלות את הכסף שביד העבד או האשה. אבל אין סברה זו קיימת במי שמוכר דבר.","מסופר, \u0003שלח רב הונא בר אבין: המוכר שדה לאשתו\u0004 — הרי זו \u0003קנתה\u0004"],["\u0003ובעל אוכל פירות\u0004 כל עוד הם נשואים, כפי שהוא אוכל פירות של שאר נכסי מלוג שלה. \u0003ברם\u0004 \u0005[אבל]\u0006 \u0003ר' אבא ור' אבהו וכל גדולי הדור אמרו: במתנה בקש ליתנו לה,\u0004 ואין הבעל אוכל פירות, \u0003ולמה כתב לה לשום מכר? כדי ליפות את כחה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003לוה מן העבד ושחררו,\u0004 או \u0003מן האשה וגרשה\u0004 — \u0003אין להן עליו כלום. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003לגלויי זוזי\u0004 \u0005[לגלות את הכספים]\u0006 שלהם \u0003הוא דבעא\u0004 \u0005[שרצה]?\u0006 ומדוע לא נאמר אף כאן שהבעל לא התכוון למכור את השדה, אלא רק להוציא מידי אשתו?","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בהלוואה, שאנו אומרים ש\u0003לא לישוי איניש\u0004 \u0005[\u0006רוצה \u0005אדם לעשות\u0006 עצמו\u0005]\u0006 \u0003\"עבד לוה לאיש מלוה\"\u0004 (משלי כב, ז) ואנו מניחים שרק לגלות את הכסף שבידם רצה.","אבל כשמוכר לה — אין שיקול כזה, והמכר קיים. ובענין זה \u0003אמר רב: המוכר שדה לאשתו\u0004 — \u0003קנתה, והבעל אוכל פירות.\u0004 אבל נתן לה את השדה \u0003במתנה\u0004 — \u0003קנתה, ואין הבעל אוכל פירות\u0004 שלגמרי נתן לה. \u0003ור' אלעזר אמר: אחד זה ואחד זה\u0004 — \u0003קנתה, ואין הבעל אוכל פירות.\u0004","מספרים: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רב חסדא עובדא\u0004 \u0005[מעשה]\u0006 בבעל שמכר שדה לאשתו \u0003כ\u0004דעת \u0003ר' אלעזר\u0004 שאין הבעל אוכל פירות. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רבן עוקבא ורבן נחמיה בני בנתיה\u0004 \u0005[בתו]\u0006 של \u0003רב לרב חסדא:\u0004 וכי \u0003שביק מר רברבי ועביד כזוטרי\u0004 \u0005[עזב אדוני את הגדולים ועשה כקטנים]\u0006 שפסק כר' אלעזר, שהיה תלמיד רב, ולא כרב שהיה גדול הדור? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ואנא נמי כרברבי עבדי\u0004 \u0005[ואני גם כן כ\u0006אנשים \u0005גדולים עשיתי],\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 \u0003אחד זה ואחד זה\u0004 — \u0003קנתה, ואין הבעל אוכל פירות.\u0004 ולא על ר' אלעזר בלבד סמכתי, אלא גם על ר' יוחנן.","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003המוכר שדה לאשתו\u0004 — \u0003לא קנתה, והבעל אוכל פירות.\u0004 נתן לה \u0003במתנה\u0004 — \u0003קנתה, ואין הבעל אוכל פירות.\u0004 ועל הדין הראשון, במוכר שדה לאשתו, תוהים: \u0003תרתי\u0004 \u0005[שני\u0006 דברים סותרים\u0005]?!\u0006 שממה שאמר רבא שלא קנתה, משמע שהכל נשאר שלו, ואף גוף הקרקע. ומצד שני אמר שהבעל אוכל פירות, משמע שגוף השדה נקנה לה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 ויש להפריד את דברי רבא לשני מקרים שונים; \u0003כאן\u0004 שאמר שלא קנתה מדובר \u0003במעות טמונין\u0004 שלא ידע על קיומם, ולא עשה מכר זה אלא כדי לגלותם. \u0003כאן\u0004 שקנה — \u0003במעות שאין טמונין,\u0004 וכפי ש\u0003אמר רב יהודה:\u0004 אם קנתה את השדה ב\u0003מעות טמונין\u0004 — \u0003לא קנתה,\u0004 ב\u0003מעות שאינן טמונין\u0004 שידע הבעל עליהם — \u0003קנתה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מקבלין פקדונות לא מן הנשים ולא מן העבדים ולא מן התינוקות,\u0004 שמן הסתם אין להם רכוש משלהם, ויש לחשוש שלקחו דבר מן הבעל או האדון או האב שלא ברשות והפקידו בידו, ואין לסייע להם בעבירה. \u0003אבל\u0004 אם בכל זאת \u0003קבל מן האשה\u0004 — \u0003יחזיר לאשה,\u0004 שהרי אינו יודע שלא שלה היה הדבר, ואינו רשאי להחזיר את הפקדון לאחר, \u0003ו\u0004אולם \u0003אם מתה\u0004 האשה — \u0003יחזיר לבעלה\u0004 שהוא יורשה. \u0003קבל מן העבד\u0004 — \u0003יחזיר לעבד\u0004 שמא היה זה פקדון של אחרים, \u0003ואם מת\u0004 — \u0003יחזיר לרבו\u0004 (אדונו)."],["\u0003קבל\u0004 פקדון \u0003מן הקטן\u0004 אינו יכול להחזיר לו, שהרי אין הקטן יכול לשמור את הדברים, אלא \u0003יעשה לו סגולה\u0004 (אוצר), \u0003ואם מת\u0004 הקטן — \u0003יחזיר ליורשיו.\u0004","\u0003וכולן,\u0004 כל אלה שמנינו \u0003שאמרו בשעת מיתתן\u0004 \u0003\"\u0004דברים אלה שהפקדנו בידו \u0003של פלוני הן\"\u0004 — \u0003יעשה כפירושן\u0004 כפי שפירשו ואמרו, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003יעשה פירוש לפירושן,\u0004 כלומר, פעמים שצריך לפרש את הדברים ולא לקבל אותם כמשמעותם.","מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רבה בר בר חנה כי קא שכבה\u0004 \u0005[כאשר מתה]\u0006 \u0003אמרה: הני כיפי\u0004 \u0005[הנזמים הללו]\u0006 שבידי הם של \u0003מרתא ובני ברתא\u0004 \u0005[בתה],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי מהימנא לך\u0004 \u0005[אם נאמנת עליך]\u0006 — \u0003עשה כפירושה\u0004 כפי שאמרה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003עשה פירוש לפירושה\u0004 וטול אותם לעצמך, כיורשה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 \u0003הכי\u0004 \u0005[\u0006ש\u0005כך]\u0006 \u0003אמר ליה:\u0004 \u0003אי אמידא לך\u0004 \u0005[אם אמודה עליך],\u0006 כלומר, שיש מקום לשער שבאמת הפקידו בידה — \u0003עשה כפירושה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003עשה פירוש לפירושה.\u0004","על מה ששנינו בברייתא שאם קיבל פקדון \u0003מן הקטן\u0004 — \u0003יעשה לו סגולה,\u0004 שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"סגולה\"? רב חסדא אמר:\u0004 יקנה לו בכך \u0003ספר תורה\u0004 שהוא גם מצוה וגם רכוש קבוע, \u0003רבה בר רב הונא אמר:\u0004 יקנה \u0003דיקלא דאכל מיניה תמרי\u0004 \u0005[דקל שאוכל ממנו תמרים].\u0006","שנינו במשנתנו ש\u0003לא לאב\u0004 חזקה \u0003בנכסי הבן ולא לבן בנכסי האב. אמר רב יוסף: אפילו חלקו\u0004 ואין הבן סמוך עוד על שולחן אביו, בכל זאת אין להם חזקה זה על זה. \u0003רבא אמר:\u0004 אם \u0003חלקו\u0004 — \u0003לא\u0004 כן הדין, אלא יש להם חזקה זה על זה ככל אדם.","\u0003אמר רב ירמיה מדפתי: עבד\u0004 \u0005[עשה]\u0006 \u0003רב פפי עובדא\u0004 \u0005[מעשה]\u0006 ופסק הלכה שאם \u0003חלקו\u0004 — \u0003לא, כ\u0004דברי \u0003רבא. אמר רב נחמן בר יצחק, אישתעי\u0004 \u0005[סיפר]\u0006 \u0003לי רב חייא מ\u0004העיר \u0003הורמיז ארדשיד,\u0004 \u0003דאישתעי ליה\u0004 \u0005[שסיפר לו]\u0006 \u0003רב אחא בר יעקב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן בר\u0004 \u0003יעקב: חלקו לא.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003חלקו לא. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בן שחלק\u0004 מאביו, \u0003ואשתו שנתגרשה\u0004 — \u0003הרי הן כשאר כל אדם\u0004 לענין חזקה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003אחד מן האחין שהיה נושא ונותן בתוך הבית\u0004 שהוא היה מתעסק במסחר עבור המשפחה, \u0003והיו אונות\u0004 (שטרות מכר) \u0003ושטרות\u0004 אחרים \u0003יוצאין על שמו\u0004 שבשטר היה כתוב שמו כבעל הנכסים או כמלוה, \u0003ואמר: שלי הם, שנפלו לי מבית אבי אמא\u0004 (שאינה אימם של שאר האחים), \u0003אמר רב: עליו להביא ראיה\u0004 שבאמת שלו הם, ואם לא — יתחלק בין האחים. \u0003ושמואל אמר: על האחין להביא ראיה\u0004 שמשל אביהם הם. \u0003אמר שמואל: מודה לי אבא\u0004 (רב, שזה היה שמו), \u0003שאם מת\u0004 — \u0003על האחין להביא ראיה\u0004 על מנת להוציא את הממון מידי היתומים של האח.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא\u0004 על דברי שמואל: \u0003כלום טענינן להו ליתמי מידי\u0004 \u0005[טוענים אנו ליתומים דבר]\u0006 ש\u0003לא טען להו אבוהון\u0004 \u0005[אביהם]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא אפיק זוגא דסרבלא וספרא דאגדתא מיתמי\u0004 \u0005[הוציא מספריים של מעילים וספר אגדה מיתומים]\u0006 \u0003בלא\u0004 שהצריך את הבעלים להביא \u0003ראיה\u0004 כאשר תבעו את היתומים להחזירם להם, הואיל ומדובר היה \u0003בדברים העשוים להשאיל ולהשכיר\u0004 שבהם אין חזקה למחזיק בהם,"],["\u0003כדשלח\u0004 \u0005[כפי ששלח]\u0006 \u0003רב הונא בר אבין: דברים העשוין להשאיל ולהשכיר\u0004 המצויים בידיו של אדם אחר, \u0003ואמר\u0004 אותו אדם \u0003\"לקוחין הן בידי\",\u0004 כלומר, קניתי אותם — \u0003אינו נאמן\u0004 עליהם. ואם כן, אין טוענים ליתומים טענה שאביהם לא היה נאמן לטעון! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003אמר רב חסדא: לא שנו,\u0004 כלומר, לא אמר רב בענין האחים, שצריך האח להביא ראיה ששלו הם הנכסים הרשומים בשטרות על שמו, \u0003אלא\u0004 ש\u0003אין חלוקין בעיסתן\u0004 כלומר, שהם שותפים בכל ואף אוכלים יחד, \u0003אבל\u0004 אם \u0003חלוקים\u0004 הם \u0003בעיסתן\u0004 — \u0003אימור\u0004 \u0005[אמור]\u0006 \u0003מעיסתו קימץ\u0004 ועל ידי כך קיבץ לו רכוש משל עצמו.","ובהלכה זו שאמרנו שצריך להביא ראיה, שואלים: \u0003ראיה במאי\u0004 \u0005[במה]?\u0006 \u0003רבה אמר: ראיה בעדים\u0004 שהכסף שקנה בו נכס הכתוב בשטר, או שהלווהו לאחר, היה משלו, \u0003רב ששת אמר: ראיה בקיום השטר\u0004 שבית דין אישרו את תוקף השטר הרשום על שמו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: הא\u0004 \u0005[הרי]\u0006 \u0003רב והא\u0004 \u0005[והרי]\u0006 \u0003שמואל, הא\u0004 \u0005[הרי]\u0006 \u0003רבה והא\u0004 \u0005[והרי]\u0006 \u0003רב ששת,\u0004 שחלוקים בבעיות אלה, \u0003מר כמאן סבירא ליה\u0004 \u0005[אדוני כמי הוא סבור]?\u0006 מה דעתך בענין זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא מתניתא ידענא\u0004 \u0005[אני ברייתא אני יודע]\u0006 ועליה אני סומך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד מן האחין שהיה נותן ונושא בתוך הבית, והיו אונות\u0004 (שטרות מכר) \u0003ושטרות יוצאין על שמו, ואמר: שלי הן, שנפלו לי מבית אבי אמא\u0004 — \u0003עליו להביא ראיה\u0004 שהם שלו.","\u0003וכן האשה\u0004 האלמנה \u0003שהיא נושאת ונותנת בתוך הבית\u0004 בענייני הבית, \u0003והיו אונות ושטרות יוצאין על שמה, ואמרה: שלי הן, שנפלו לי\u0004 בירושה \u0003מבית אבי אבא או מבית אבי אמא\u0004 — \u0003עליה להביא ראיה.\u0004 ואם כן הרי זה כשיטת רב.","כיון שהובאה ברייתא זו מבררים את האמור בה: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003\"וכן\"?\u0004 מדוע צריך להוסיף גם הלכה זו, והרי לכאורה הוא הוא הדין? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אשה כיון דשביחא\u0004 \u0005[שמשובח]\u0006 \u0003לה\u0004 בעיניה \u0003מילתא\u0004 \u0005[הדבר]\u0006 \u0003דאמרי קא טרחא קמי יתמי\u0004 \u0005[שאומרים\u0006 ש\u0005היא טורחת לפני היתומים]\u0006 ועושה עבורם — \u0003לא גזלה מיתמי\u0004 \u0005[אינה גוזלת מהיתומים]\u0006 ויש לסמוך עליה אם טוענת שהרכוש הרשום על שמה הוא שלה, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין סומכים על כך, ואף היא צריכה להביא ראיה ששלה הוא.","שנינו במשנה: \u0003במה דברים אמורים?\u0004 — \u0003במחזיק, אבל בנותן מתנה והאחין שחלקו וכו',\u0004 אם גדר ופרץ כלשהו הרי זו חזקה. ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל הני דאמרינן\u0004 \u0005[אלה שאמרנו]\u0006 קודם, שהחזיקו בשדה שלוש שנים \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני חזקה נינהו\u0004 \u0005[הם]?\u0006 וכי הם אינם יכולים לקנות קרקע בדרך זו?","ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך היא שנויה],\u0006 כך יש להבינה: \u0003במה דברים אמורים?\u0004 — \u0003בחזקה שיש עמה טענה,\u0004 כלומר, שבאה כנגד ערעור על הבעלות, \u0003כגון מוכר אומר \"לא מכרתי\" ולוקח אומר \"לקחתי\",\u0004 ואז החזקה של שלוש שנים היא הוכחה.","\u0003אבל חזקה שאין עמה טענה, כגון נותן מתנה, והאחין שחלקו, והמחזיק בנכסי הגר, דלמקני בעלמא\u0004 \u0005[של\u0006 שם \u0005קנין בלבד]\u0006 \u0003הוא,\u0004 שעל ידי מעשה החזקה נקנה החפץ למקבל, ולא לשם הוכחה על בעלות, אם \u0003נעל\u0004 או \u0003גדר\u0004 או \u0003פרץ כל שהוא\u0004 — \u0003הרי זו חזקה.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב הושעיא ב\u0004ברייתא של מסכת \u0003קדושין\u0004 ששנויה \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003לוי: נעל, גדר, פרץ כל שהוא,\u0004 אם עשה זאת \u0003בפניו\u0004 של המוכר — \u0003הרי זו חזקה.\u0004 ותוהים: \u0003בפניו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בפניו\u0004 — \u0003לא?\u0004 הרי מעשה חזקה עשה! \u0003אמר רבא, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם עשה זאת \u0003בפניו\u0004 — \u0003לא צריך\u0004 הבעלים \u0003למימר ליה\u0004 \u0005[לומר לו]\u0006 \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה].\u0006 שכיון שעושה בפניו ומדעתו, הרי אין צורך שיאמר לו במפורש שיעשה חזקה לשם קנין."],["ואם עשה זאת \u0003שלא בפניו\u0004 — \u0003צריך למימר ליה\u0004 \u0005[לומר לו]\u0006 \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב:\u0004 ב\u0003מתנה היאך\u0004 \u0005[כיצד]?\u0006 האם צריך לומר לו \"לך החזק וקנה\" כאשר מחזיק שלא בפניו? \u0003אמר שמואל: מאי תבעי ליה\u0004 \u0005[מה מסופק לו]\u0006 \u0003לאבא,\u0004 רב? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה מכר דקא יהיב ליה זוזי\u0004 \u0005[שהוא נותן לו\u0006 למקנה \u0005כסף],\u0006 \u0003אי אמר ליה\u0004 \u0005[אם אומר לו]\u0006 \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 מועיל מעשה החזקה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 מועיל הדבר, \u0003מתנה\u0004 שאין בה נתינת דמים למקנה, \u0003לא כל שכן\u0004 שלא יועיל מעשה החזקה בלא ציווי מפורש? ומעירים: \u0003ורב סבר\u0004 שיש גם צד אחר, שאפשר לומר: \u0003מאן דיהיב\u0004 \u0005[מי שנותן]\u0006 \u0003מתנה, בעין יפה\u0004 הוא \u0003יהיב\u0004 \u0005[נותן]\u0006 וגומר בדעתו להקנות, בלא שיהא צורך באמירה מפורשת.","שנינו במשנה שאם נעל גדר ופרץ כל שהוא הרי זו חזקה. \u0003ו\u0004מבארים: \u0003כמה\u0004 הוא שיעור \u0003כל שהוא?\u0004 — \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: גדר\u0004 קודם לכן \u0003גדר, והשלימו\u0004 עכשיו \u0003ל\u0004גובה \u0003עשרה\u0004 טפחים, \u0003ו\u0004כן אם \u0003פרץ פרצה כדי שיכנס ויצא בה\u0004 — \u0003הרי זו חזקה.\u0004","ומבררים: \u0003האי גדר\u0004 \u0003היכי דמי\u0004 \u0005[אותה גדירה\u0006 שאמרנו \u0005כיצד בדיוק הדבר]?\u0006 \u0003אילימא דמעיקרא\u0004 \u0005[אם תאמר שמתחילה]\u0006 \u0003לא הוו סלקי לה\u0004 \u0005[היו עולים בה\u0006 לחצר\u0005]\u0006 \u0003והשתא נמי\u0004 \u0005[ועכשיו גם כן]\u0006 \u0003לא סלקי לה\u0004 \u0005[עולים בה],\u0006 \u0003מאי עבד\u0004 \u0005[מה עשה]\u0006 על ידי גדירתו? \u0003ואלא\u0004 תאמר \u0003דמעיקרא הוו סלקי לה\u0004 \u0005[שמתחילה היו עולים בה]\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 \u0003לא סלקי לה\u0004 \u0005[עולים בה],\u0006 אם כן \u0003טובא עבד\u0004 \u0005[הרבה עשה]\u0006 ואין לקרוא לכך \"כל שהוא\"! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דמעיקרא הוו סלקי לה ברווחא, והשתא קא סלקי לה בדוחקא\u0004 \u0005[שמתחילה היו עולים בה ברווח, ועכשיו הם עולים בה בדוחק].\u0006","ושואלים: \u0003האי\u0004 \u0005[אותה]\u0006 \u0003פרצה\u0004 שהזכרנו \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היתה]?\u0006 \u0003אילימא דמעיקרא הוו עיילי בה והשתא נמי עיילי\u0004 \u0005[אם תאמר שמתחילה היו נכנסים בה\u0006 דרך הפרצה לחצר \u0005ועכשיו גם כן נכנסים]\u0006 \u0003בה, מאי עבד\u0004 \u0005[מה עשה]\u0006 על ידי כך? \u0003ואלא\u0004 תאמר \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003לא הוו עיילי\u0004 \u0005[היו נכנסים]\u0006 \u0003בה והשתא קא עיילי\u0004 \u0005[ועכשיו נכנסים]\u0006 \u0003בה\u0004 אם כן \u0003טובא עבד\u0004 \u0005[הרבה עשה],\u0006 ואין זה \"כל שהוא\"! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה \u0003דמעיקרא הוו עיילי\u0004 \u0005[שמתחילה היו נכנסים]\u0006 \u0003בה בדוחקא\u0004 \u0005[בדוחק]\u0006 \u0003והשתא עיילי\u0004 \u0005[ועכשיו נכנסים]\u0006 \u0003בה ברווחא\u0004 \u0005[ברווח].\u0006","\u0003אמר ר' אסי אמר ר' יוחנן: נתן צרור\u0004 בגדר \u0003והועיל\u0004 במעשהו, או \u0003נטל\u0004 ממנה \u0003צרור והועיל\u0004 — \u0003הרי זו חזקה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"נתן\" ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"נטל\"\u0004 בענין זה?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003נתן צרור וסכר מיא מינה\u0004 \u0005[\u0006את \u0005המים ממנה],\u0006 שהיה זרם מים מגיע לשטוף את החצר, ונתן צרור בגדר ואין המים יכולים להיכנס, או \u0003נטל צרור ואפיק מיא מינה\u0004 \u0005[והוציא מים ממנה],\u0006 שנתמלאה החצר במים ופתח פתח קטן שייצאו המים מן החצר, \u0003האי\u0004 \u0005[זה]\u0006 רק \u0003מבריח ארי מנכסי חברו הוא,\u0004 כלומר, רק מנע נזק, וכדרך שאדם עושה עבור חבירו. אבל לא עשה מעשה של תיקון בשדה כדרך שאדם עושה בשלו! \u0003אלא, נתן צרור\u0004 — \u0003דצמד לה מיא\u0004 \u0005[ש\u0006על ידי כך \u0005חיבר,\u0006 הביא \u0005אליה המים]\u0006 וגרם להשקות את השדה, \u0003נטל צרור וארוח\u0004 \u0005[והרוויח,\u0006 והוסיף\u0005]\u0006 \u0003לה מיא\u0004 \u0005[מים].\u0006","\u0003ואמר רב אסי אמר ר' יוחנן: שתי שדות ומצר\u0004 (גבול) \u0003אחד ביניהן,\u0004 אם \u0003החזיק באחת מהן לקנותה\u0004 — הרי זו \u0003קנאה;\u0004"],["אם התכוון \u0003לקנות אותה ואת חברתה\u0004 — \u0003אותה קנה,\u0004 ואילו את \u0003חברתה לא קנה\u0004 לפי שהאחרת מופסקת מזו על ידי המצר. אם עשה בה מעשה חזקה כדי \u0003לקנות את חברתה\u0004 — \u0003אף אותה לא קנה,\u0004 שהרי לא החזיק במה שנתכוון לקנות, ואין אדם קונה דבר כשאינו מתכוון לקנותו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא:\u0004 אם \u0003החזיק באחת מהן לקנות אותה ואת המצר ואת חברתה, מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003מצר דארעא\u0004 \u0005[המצר של הקרקע],\u0006 של שתי הקרקעות, \u0003חד\u0004 \u0005[אחד]\u0006 \u0003הוא,\u0004 ומחבר את שתיהן, \u0003וקני\u0004 \u0005[ו\u0006הרי הוא \u0005קונה]\u0006 את הכל. \u0003או דלמא האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[שמא זה לעצמו עומד וזה לעצמו עומד]?\u0006 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: החזיק במצר\u0004 שבין השדות \u0003לקנות\u0004 את \u0003שתיהן, מהו\u0004 הדין בכגון זה? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003מצר אפסרא דארעא\u0004 \u0005[\u0006כ\u0005אפסר של הקרקע]\u0006 \u0003הוא וקני\u0004 \u0005[וקונה]\u0006 את הכל, כדרך שאדם קונה בהמה על ידי מסירת האפסר לידיו. \u0003או דלמא האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[שמא זה לעצמו עומד וזה לעצמו עומד],\u0006 שאין המצר מחובר לשדה כאפסר לבהמה? אף שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","ובדומה לדברי ר' יוחנן בענין שדות \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 היו \u0003שני בתים זה לפנים מזה,\u0004 אם \u0003החזיק בחיצון לקנותו\u0004 — \u0003קנאו.\u0004 אם התכוון \u0003לקנות אותו ואת הפנימי\u0004 — את ה\u0003חיצון קנה,\u0004 ואילו את ה\u0003פנימי לא קנה.\u0004 אם החזיק בו כדי \u0003לקנות את הפנימי\u0004 — \u0003אף\u0004 את ה\u0003חיצון נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנה.\u0004","אם \u0003החזיק בפנימי לקנותו\u0004 — \u0003קנאו.\u0004 אם התכוון \u0003לקנות אותו ואת החיצון\u0004 — \u0003קנה שניהן,\u0004 משום שהחיצון משועבד לפנימי, שהרי המשתמש בפנימי עובר דרך החיצון. אם החזיק בפנימי כדי \u0003לקנות את החיצון\u0004 — \u0003אף\u0004 את ה\u0003פנימי לא קנה\u0004 שהרי לא החזיק במה שנתכוון לקנות.","\u0003אמר רב נחמן אמר רבה בר אבוה: הבונה פלטרין\u0004 (ארמונות) \u0003גדולים בנכסי הגר,\u0004 בקרקעותיו של גר שמת ואין לו יורשים, \u0003ובא אחר והעמיד להן דלתות\u0004 — \u0003קנה\u0004 השני. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003קמא, לבני בעלמא\u0004 \u0005[הראשון, לבנים בלבד]\u0006 \u0003הוא דאפיך\u0004 \u0005[שהפך].\u0006 כלומר, בניית הבית שלא הושלמה אינה נחשבת כמעשה גמור לענין קנין הקרקע.","\u0003אמר רב דימי בר יוסף אמר ר' אלעזר: המוצא פלטרין\u0004 (ארמון) \u0003בנכסי הגר, וסד בהן סיוד אחד או כיור אחד\u0004 — \u0003קנאן.\u0004 ושואלים: \u0003וכמה,\u0004 מה השיעור של סיוד זה? \u0003אמר רב יוסף: אמה\u0004 אחת. \u0003אמר רב חסדא: ו\u0004דווקא כשעושה את זה \u0003כנגד הפתח\u0004 שהוא ניכר ובולט לעין.","\u0003אמר רב עמרם: האי מילתא\u0004 \u0005[דבר זה]\u0006 \u0003אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב ששת, ואנהרינהו עינין ממתניתא\u0004 \u0005[והאיר\u0006 את \u0005עינינו מברייתא]\u0006 שרומזת לדבר זה. שכך אמר: \u0003המציע מצעות בנכסי הגר\u0004 — \u0003קנה. ואנהרינהו עינין ממתניתא\u0004 \u0005[והאיר\u0006 את \u0005עינינו מברייתא],\u0006 \u0003מאי היא\u0004 \u0005[מה הוא]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיצד\u0004 קונה אדם עבד \u0003בחזקה?\u0004 — אם העבד \u0003נעל לו\u0004 את \u0003מנעלו, או התיר לו\u0004 את \u0003מנעלו, או שהוליך\u0004 את \u0003כליו אחריו לבית המרחץ,\u0004 או \u0003הפשיטו,\u0004 או \u0003הרחיצו,\u0004 או \u0003סכו,\u0004 או \u0003גרדו\u0004 (הסיר את שמן הסיכה מגופו), או \u0003הלבישו,\u0004 או \u0003הנעילו,\u0004 או \u0003הגביהו,\u0004 אם עשה אחד מכל אלו — \u0003קנאו, אמר ר' שמעון: לא תהא חזקה גדולה מהגבהה, שהגבהה קונה בכל מקום.\u0004","על דברי ר' שמעון שואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 שהרי אף התנא הראשון אמר שאם הגביהו קנאו! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 לדעת התנא הראשון אם \u0003הגביהו\u0004 העבד \u0003לרבו\u0004 — \u0003קנאו\u0004 הרב, שהרי עשה העבד עבודה בשבילו, אבל אם \u0003הגביה רבו לו\u0004 שהרים את העבד כדי לקנותו — \u0003לא קנאו.\u0004 ועל כך \u0003אמר ר' שמעון: לא תהא חזקה\u0004 של שימוש \u0003גדולה מהגבהה, שהגבהה\u0004 של חפץ כדי לקנותו \u0003קונה בכל מקום\u0004 אף במקום שאין קניינים אחרים מועילים, ובוודאי שתועיל במקום שחזקה של שימוש מועילה.","\u0003אמר רב ירמיה ביראה\u0004 (מן העיר בירי) \u0003אמר רב יהודה: האי מאן\u0004"],["\u0003דשדא ליפתא בי פילי דארעא\u0004 \u0005[מי שהשליך זרעי לפת בתוך סדקי הקרקע]\u0006 של \u0003גר\u0004 — \u0003לא הוי\u0004 \u0005[אין זו]\u0006 \u0003חזקה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003בעידנא דשדא\u0004 \u0005[בזמן שהשליך]\u0006 \u0003לא הוי שבחא\u0004 \u0005[היה\u0006 בזה \u0005שבח]\u0006 ותועלת לשדה, \u0003השתא דקא שבח\u0004 \u0005[עכשיו שמשביח]\u0006 השדה כשצומחת הלפת — \u0003ממילא קא שבח\u0004 \u0005[מעצמו הוא משביח].\u0006","\u0003אמר שמואל: האי מאן דפשח דיקלא\u0004 \u0005[מי שקצץ\u0006 ענפי \u0005דקל],\u0006 אם היה זה \u0003אדעתא דדיקלא\u0004 \u0005[על דעת\u0006 לקנות בכך את \u0005הדקל]\u0006 — \u0003קני\u0004 \u0005[קנה],\u0006 ואם \u0003אדעתא דחיותא\u0004 \u0005[\u0006אם \u0005על דעת\u0006 לתת \u0005לחיות,\u0006 לבהמות\u0005]\u0006 לאכול מן הענפים — \u0003לא קני\u0004 \u0005[קנה]\u0006 את הדקל. ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק],\u0006 כיצד יודעים את כוונתו? אם \u0003שקל מהאי גיסא ומהאי גיסא\u0004 \u0005[לקח\u0006 ענפים \u0005מצד זה ומצד זה]\u0006 — \u0003אדעתא דדיקלא\u0004 \u0005[על דעת הדקל]\u0006 הוא עושה, שמסייע לצמיחתו לגובה. אם עשה זאת \u0003כולא מחד גיסא\u0004 \u0005[הכל מצד אחד]\u0006 — \u0003אדעתא דחיותא\u0004 \u0005[\u0006הרי זה \u0005על דעת\u0006 להאכיל את \u0005החיות].\u0006","\u0003ואמר שמואל: האי מאן דזכי זיכיא\u0004 \u0005[מי שמנקה]\u0006 את השדה מעצים, אם עשה זאת \u0003אדעתא דארעא\u0004 \u0005[על דעת\u0006 לתקן את \u0005הקרקע]\u0006 — \u0003קני\u0004 \u0005[קנה]\u0006 את הקרקע, ואם \u0003אדעתא דציבי\u0004 \u0005[על דעת\u0006 ללקט את \u0005העצים]\u0006 — \u0003לא קני\u0004 \u0005[קנה].\u0006 ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר],\u0006 כיצד מבינים את כוונתו? אם \u0003שקל רברבי וזוטרי\u0004 \u0005[לקח גדולים וקטנים]\u0006 — הרי זה \u0003אדעתא דארעא\u0004 \u0005[על דעת\u0006 לתקן את \u0005הקרקע],\u0006 ואם \u0003שקל רברבי ושבק זוטרי\u0004 \u0005[לקח גדולים והניח קטנים]\u0006 — \u0003אדעתא דציבי\u0004 \u0005[\u0006\u0005על דעת העצים\u0006 עשה\u0005].\u0006","\u0003ואמר שמואל: האי מאן דאתקיל תיקלא\u0004 \u0005[מי שהסיר גבשושיות]\u0006 ויישר את האדמה, אם עשה זאת \u0003אדעתא דארעא\u0004 \u0005[על דעת\u0006 לתקן \u0005את\u0006 \u0005הקרקע]\u0006 לצורך חרישת השדה — \u0003קני\u0004 \u0005[קנה],\u0006 ואם עשה זאת \u0003אדעתא דבי דרי\u0004 \u0005[על דעת\u0006 לעשות שם \u0005גורן]\u0006 — \u0003לא קני\u0004 \u0005[קנה].\u0006 ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 ניכר \u0005הדבר]?\u0006 אם \u0003שקל מוליא ושדא בנצא\u0004 \u0005[נטל תל והשליך בגומא]\u0006 — הרי זה \u0003אדעתא דארעא\u0004 \u0005[על דעת הקרקע],\u0006 לצורך חרישה של השדה כולו. אבל אם יישר את הקרקע \u0003מוליא במוליא ונצא בנצא\u0004 \u0005[\u0006את \u0005התל ב\u0006מקום \u0005התל\u0006 ואת \u0005הגומא ב\u0006מקום \u0005הגומא]\u0006 — הרי זה \u0003אדעתא דבי דרי\u0004 \u0005[על דעת\u0006 לעשות \u0005גורן].\u0006","\u0003ואמר שמואל: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003פתח\u0004 והניח \u0003מיא בארעא\u0004 \u0005[מים\u0006 להיכנס \u0005ל\u0006חלקת \u0005קרקע],\u0006 אם עשה זאת \u0003אדעתא דארעא\u0004 \u0005[על דעת\u0006 לתקן את \u0005הקרקע]\u0006 — \u0003קני\u0004 \u0005[\u0006\u0005קנה],\u0006 ואם עשה זאת \u0003אדעתא דכוורי\u0004 \u0005[על דעת\u0006 שיצוד את \u0005הדגים]\u0006 שנמצאים במים — \u0003לא קני\u0004 \u0005[קנה].\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה\u0006 ניכר \u0005הדבר]?\u0006 אם \u0003פתח תרי בבי, חד מעייל וחד מפיק\u0004 \u0005[שני פתחים, אחד מכניס\u0006 את המים \u0005ואחד מוציא]\u0006 — הרי זה סימן שעשה זאת \u0003אדעתא דכוורי\u0004 \u0005[על דעת הדגים]\u0006 שיישטפו המים החוצה ויישארו הדגים באותה חלקה. ואם פתח רק \u0003חד בבא\u0004 \u0005[פתח אחד]\u0006 — הרי זה \u0003אדעתא דארעא\u0004 \u0005[על דעת הקרקע].\u0006","מסופר: \u0003ההיא איתתא דאכלה דיקלא בתפשיחא תליסר שנין\u0004 \u0005[אשה אחת היתה אוכלת דקל\u0006 של הפקר \u0005בקציצה\u0006 שהיתה קוצצת ממנו במשך \u0005שלוש עשרה שנה].\u0006 \u0003אתא ההוא רפיק תותיה פורתא\u0004 \u0005[בא אחד\u0006 ו\u0005עדר תחתיו מעט].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003לוי, ואמרי לה קמיה\u0004 \u0005[ויש אומרים\u0006 שבא \u0005לפני]\u0006 \u0003מר עוקבא, אוקמיה בידיה\u0004 \u0005[העמיד את הדקל בידו]\u0006 של העודר. \u0003אתאי קא צווחא קמיה\u0004 \u0005[באה\u0006 האשה ו\u0005צווחה לפניו],\u0006 \u0003אמר לה: מאי אעביד\u0004 \u0005[מה אעשה]\u0006 \u0003לך,\u0004 ש\u0003לא אחזיקת כדמחזקי אינשי\u0004 \u0005[החזקת כמו שבני אדם\u0006 עושים \u0005חזקה].\u0006","\u0003אמר רב: הצר צורה\u0004 (מצייר דבר) \u0003בנכסי הגר,\u0004 כגון שמצייר צורה על הקיר או כיוצא בו — הרי זה \u0003קנה,\u0004 ש\u0003רב לא קני לגנתא דבי\u0004 \u0005[קנה את הגינה של בית]\u0006 \u0003רב\u0004 מן ההפקר \u0003אלא בצורתא\u0004 \u0005[\u0006על ידי שעשה בה \u0005צורה].\u0006","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003שדה המסויימת\u0004 (המוגדרת) \u0003במצריה,\u0004 שיש לה מצרים ניכרים מכל צד, \u0003אמר רב הונא אמר רב: כיון שהכיש בה\u0004 הכאת \u0003מכוש אחד\u0004 בעדירתו בקרקע — \u0003קנה\u0004 את \u0003כולה, ושמואל אמר: לא קנה אלא\u0004 את \u0003מקום מכושו בלבד.\u0004"],["\u0003ושאינה מסויימת במצריה, עד כמה\u0004 יקנה בהכאת מכוש אחת? \u0003אמר רב פפא: כדאזיל תיירא דשורי והדר\u0004 \u0005[כמו שהולך השוור,\u0006 נוהג השוורים, \u0005וחוזר],\u0006 כלומר, כדי שיעור רגיל של תלם חרישה ממקום שעדר בו.","\u0003אמר רב יהודה אמר שמואל: נכסי גוי\u0004 שמכרם לישראל בכסף \u0003הרי הן\u0004 במשך זמן מסויים, עד שיזכה בהם הקונה, הפקר \u0003כמדבר, כל המחזיק בהן זכה בהן. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003גוי מכי מטו זוזי לידיה אסתלק ליה\u0004 \u0005[כאשר הגיע הכסף לידו הסתלק לו]\u0006 מן הבעלות, \u0003ישראל\u0004 שקנה ממנו את השדה \u0003לא קני\u0004 \u0005[קונה]\u0006 \u0003עד דמטי שטרא לידיה\u0004 \u0005[שמגיע השטר לידו].\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 במשך הזמן שבין נתינת הכסף לבין קבלת השטר \u0003הרי הן כמדבר, וכל המחזיק בהן זכה בהן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: דינא דמלכותא דינא\u0004 \u0005[דין המלכות\u0006 הוא \u0005דין],\u0006 \u0003ומלכא\u0004 \u0005[והמלך]\u0006 \u0003אמר: לא ליקני ארעא\u0004 \u0005[תקנה הקרקע]\u0006 לאדם \u0003אלא באיגרתא\u0004 \u0005[בשטר]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אנא לא ידענא\u0004 \u0005[אני איני יודע]\u0006 לישב את הסתירה, אבל \u0003עובדא הוה\u0004 \u0005[מעשה היה]\u0006 \u0003ב\u0004מקום הנקרא \u0003דורא דרעותא, בישראל דזבן ארעא\u0004 \u0005[שקנה קרקע]\u0006 \u0003מגוי\u0004 בכסף, \u0003ואתא\u0004 \u0005[ו\u0006בינתיים \u0005בא]\u0006 \u0003ישראל אחרינא רפיק\u0004 \u0005[אחר\u0006 ו\u0005עדר]\u0006 \u0003בה פורתא\u0004 \u0005[מעט],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יהודה, אוקמה בידא\u0004 \u0005[\u0006ו\u0005העמיד אותה,\u0006 את הקרקע \u0005בידו]\u0006 של ה\u0003שני.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003דורא דרעותא קאמרת\u0004 \u0005[אומר אתה]?\u0006 משם אין ראיה, כי \u0003התם באגי מטמרי הוו\u0004 \u0005[שם שדות טמונים,\u0006 מוסתרים, \u0005היו],\u0006 \u0003דאינהו גופייהו\u0004 \u0005[שהם עצמם],\u0006 בעלי השדות \u0003לא הוו יהבי טסקא למלכא\u0004 \u0005[היו נותנים\u0006 את \u0005המס למלך],\u0006 \u0003ומלכא\u0004 \u0005[והמלך]\u0006 \u0003אמר: מאן דיהיב טסקא ליכול ארעא\u0004 \u0005[מי שיתן\u0006 את \u0005המס\u0006 הוא \u0005שיאכל\u0006 מן \u0005הקרקע],\u0006 ולכן אף לגוי המוכר לא היתה בעלות ממש על הקרקע, ולא היתה לו זכות ויכולת למכור לפי דין המלכות, וזה המחזיק זכה משום שקיבל על עצמו לשלם את המס. אבל במקרה רגיל לא יוכל אדם לזכות בשדה עד שיגיע לידו שטר מכר מן הגוי.","מסופר: \u0003רב הונא זבן ארעא\u0004 \u0005[קנה קרקע]\u0006 \u0003מגוי, אתא\u0004 \u0005[בא]\u0006 \u0003ישראל אחר רפיק\u0004 \u0005[עדר]\u0006 \u0003בה פורתא\u0004 \u0005[מעט].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב נחמן, אוקמה בידיה\u0004 \u0005[העמיד אותה בידו]\u0006 של אותו אדם שחפר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרב נחמן: \u0003מאי דעתיך\u0004 \u0005[מה דעתך]?\u0006 ממה הסקת כך? ממה ש\u0003אמר שמואל: נכסי גוי הרי הן כמדבר, וכל המחזיק בהם זכה?\u0004 —"],["\u0003ליעבד\u0004 \u0005[יעשה]\u0006 \u0003לי מר כאידך\u0004 \u0005[אדוני כ\u0006דבר \u0005אחר]\u0006 שאמר \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 שהעודר בקרקע הפקר \u0003לא קנה אלא\u0004 את \u0003מקום מכושו בלבד! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בהאי אנא כשמעתין סבירא לי\u0004 \u0005[ב\u0006ענין \u0005זה אני כשמועתנו אני סבור],\u0006 ש\u0003אמר רב הונא אמר רב: כיון שניכש בה מכוש אחד\u0004 — \u0003קנה כולה.\u0004","ומסופר, \u0003שלח רב הונא בר אבין: ישראל שלקח\u0004 (קנה) \u0003שדה מגוי, ובא ישראל אחר והחזיק בה\u0004 — \u0003אין מוציאים אותה מידו. וכן היה ר' אבין ור' אילעא וכל רבותינו שוין\u0004 (מסכימים) \u0003בדבר\u0004 זה.","\u0003אמר רבה, הני תלת מילי אישתעי\u0004 \u0005[שלושה דברים אלה סיפר]\u0006 \u0003לי עוקבן בר נחמיה ריש גלותא משמיה\u0004 \u0005[ראש הגולה משמו]\u0006 של \u0003שמואל:\u0004 אחד, \u0003דינא דמלכותא דינא\u0004 \u0005[דין המלכות דין\u0006 הוא\u0005]\u0006 ויש לנהוג לפיו, \u0003ואריסותא דפרסאי\u0004 \u0005[ואריסות של פרסים]\u0006 היא \u0003עד ארבעין שנין\u0004 \u0005[ארבעים שנה],\u0006 שבדיניהם חזקת קרקע היא בארבעים שנה של שימוש. \u0003והני זהרורי דזבין ארעא לטסקא\u0004 \u0005[ואותם פקידי מס שמכרו\u0006 את \u0005הקרקע\u0006 כדי \u0005ל\u0006שלם את \u0005מס הקרקעות]\u0006 — \u0003זבינהו זביני\u0004 \u0005[מכרם מכר],\u0006 ומותר לקנות מהם את השדות.","ומסבירים: \u0003והני מילי לטסקא\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005למס הקרקעות],\u0006 \u0003אבל לכרגא\u0004 \u0005[למס הגולגולת]\u0006 \u0003לא; מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003כרגא אקרקף דגברי מנח\u0004 \u0005[על ראש האנשים מונח],\u0006 כלומר, הוא מס המוטל על האנשים עצמם, ואינו קשור בקרקעות, והרי זה גזל ביד הפקידים. \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 כל דבר, \u0003אפילו שערי דכדא משתעבדי לכרגא\u0004 \u0005[שעורים שבכד משתעבדות ל\u0006תשלום \u0005מס הגולגולת].\u0006","\u0003אמר רב אשי: אמר לי הונא בר נתן, קשי\u0004 \u0005[התקשה]\u0006 \u0003בה\u0004 בהלכה זו \u0003אמימר: אם כן,\u0004 לפי זה \u0003בטלת\u0004 דין \u0003ירושת בנו הבכור\u0004 של אדם החייב מס זה למלכות, \u0003דהוה ליה\u0004 \u0005[שהרי הוא נעשה]\u0006 \u0003ראוי,\u0004 שכל הרכוש שהשאיר האב אינו נחשב כשייך ממש ליורשים, אלא רק כראוי לבוא להם בירושה, שהרי גובי המיסים יכולים ליטול כל חלק מרכוש אביהם אם לא פרע את המס. \u0003ו\u0004הרי הכלל הוא ש\u0003אין הבכור נוטל\u0004 פי שנים \u0003בראוי כבמוחזק\u0004 אלא כשאר האחים.","ומוסיף הונא בר נתן, \u0003אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו טסקא נמי\u0004 \u0005[במס הקרקע גם כן]\u0006 המוטל על נכסי האב, נחשיב בגללו את כל הרכוש כראוי ולא כמוחזק! \u0003אלא מה אית\u0004 \u0005[יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]?\u0006 שאין בכך לבטל מכל וכל את ירושת הבן הבכור, וכגון במקרה \u0003דיהיב טסקא ומית\u0004 \u0005[שנתן\u0006 את \u0005מס הקרקע ומת],\u0006 ואין עליו עוד חוב למלכות, והשדה הוא שלו בשלמות. \u0003הכא נמי דיהיב כרגא ומית\u0004 \u0005[כאן גם כן\u0006","אין ירושת הבכור מתבטלת במי \u0005שנתן מס הגולגולת ומת].\u0006 ועוד \u0003אמר רב אשי, אמר לי הונא בר נתן: שאילתינהו לספרי\u0004 \u0005[שאלתי את הסופרים],\u0006 כותבי השטרות ופסקי הדין של \u0003רבא, ואמרו לי: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 שכל נכסיו של אדם משתעבדים למס הגולגולת. ומעירים: \u0003ולא היא\u0004 (אין הדבר כן), אלא \u0003התם לאוקומי מילתיה\u0004 \u0005[שם להעמיד\u0006 את \u0005דבריו]\u0006 שאמר קודם \u0003הוא\u0004 ש\u0003אמר.\u0004","\u0003ואמר רב אשי: פרדכת מסייע מתא\u0004 \u0005[אדם בטל\u0006 שאינו עובד בכל זאת צריך \u0005לסייע\u0006 ולהשתתף בתשלום מיסי \u0005העיר]\u0006 אף על פי שאינו מרויח בה דבר. \u0003והני מילי דאצילתיה מתא\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005שהצילה אותו העיר],\u0006 שהשתדלו עבורו והפחיתו מן המס המוטל עליו, \u0003אבל אנדיסקי\u0004 \u0005[גובי מיסים]\u0006 שויתרו, ולא נטלו מאותו אדם — \u0003סיעתא דשמיא היא\u0004 \u0005[סיוע מן השמים הוא]\u0006 ואינו צריך לשלם יחד עם האחרים.","\u0003אמר רב אסי אמר ר' יוחנן: המצר\u0004 שבין השדות, \u0003והחצב\u0004 ששותלים כסימן לגבול בין שדה לשדה \u0003מפסיקין בנכסי הגר,\u0004 שאם קנה בחזקה קרקע הגר, הרי הוא קונה עד המצר או החצב ולא מעבר מזה, \u0003אבל לענין פאה וטומאה\u0004 — \u0003לא,\u0004 אין אלה מפסיקים, אלא הכל נחשב כשדה אחד. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אפילו לפאה וטומאה\u0004 מפסיקים הם.","ומעתה מסבירים את הדברים הללו, \u0003פאה, מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 עניינה? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ואלו מפסיקין לפאה:\u0004 שכל אחד מהחלקים המחולקים על ידם נחשב כשדה לעצמו, וצריך להפריש ממנו פאה בפני עצמו: \u0003הנחל\u0004 העובר בתוך השדה, או \u0003השלולית\u0004 (מקום שמים נאספים, או עוברים בו),"],["\u0003ודרך הרבים\u0004 שרוחבה לפחות שש עשרה אמה, \u0003ודרך היחיד\u0004 שרוחבה ארבע אמות, \u0003ושביל הרבים, ושביל היחיד הקבוע בין בימות החמה ובין בימות הגשמים\u0004 הרי הם עושים גבול לשדה. וכיוצא בזה נחלקו האמוראים בשיטת ר' יוחנן האם המצר והחצב אף הם חוצים את השדה, וצריך להניח פאה לכל חלק.","ועוד מבררים: \u0003טומאה, מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 לאיזה ענין יכולים המצר והחצב להיות הפסק? ואומרים: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנכנס לבקעה\u0004 (מישור) \u0003בימות הגשמים\u0004 שאז אין הרבים מהלכים שם, ודינה כרשות היחיד שספק טומאה שבה טמא, \u0003וטומאה\u0004 היתה מצויה \u0003בשדה פלונית\u0004 (מסויימת) באותה בקעה, \u0003ואמר: הלכתי למקום הלז,\u0004 לאותה בקעה, \u0003ואיני יודע אם נכנסתי לאותו מקום\u0004 שיש בו טומאה \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003ר' אליעזר מטהר, וחכמים מטמאין.\u0004","\u0003שהיה ר' אליעזר אומר: ספק ביאה\u0004 אם יש לו ספק אם נכנס לאותו מקום — הרי הוא \u0003טהור, ספק מגע טומאה\u0004 — הרי זה \u0003טמא.\u0004 ובענין זה אמר רבין בשם ר' יוחנן שמצר וחצב מגדירים מקום לעצמו.","ומדברי ר' אבין בשם ר' יוחנן מדייקים: לענין פאה וטומאה מפסיקים המצר והחצב, \u0003אבל ל\u0004ענין \u0003שבת\u0004 — \u0003לא,\u0004 אין מצר וחצב נחשבים כמחלקים את השדה לרשויות נפרדות.","\u0003רבא אמר: אפילו לענין שבת\u0004 מפרידים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הוציא חצי גרוגרת\u0004 (תאנה יבשה) מרשות היחיד \u0003לרשות הרבים והניחה\u0004 שם, \u0003וחזר והוציא חצי גרוגרת אחרת,\u0004 אם היה הדבר \u0003בהעלם אחד\u0004 (שגגה אחת), שלא נזכר בינתיים שהדבר אסור או שיום השבת הוא — הרי שתי ההוצאות הללו מצטרפות. וכיון שהוציא שיעור גרוגרת, הרי זה \u0003חייב\u0004 קרבן חטאת. ואם היה זה \u0003בשני העלמות,\u0004 שלאחר שהוציא חצי גרוגרת נזכר שמעשה זה אסור או ששבת היום, וחזר ושכח, ושוב הוציא חצי גרוגרת — \u0003פטור.\u0004","\u0003ר' יוסי אומר:\u0004 אף אם היה הדבר \u0003בהעלם אחד\u0004"],["רק אם היה הדבר \u0003ברשות אחת,\u0004 באותה רשות הרבים עצמה, שחזר והוציא אליה חצי גרוגרת נוספת — \u0003חייב,\u0004 אם היה זה \u0003בשתי רשויות\u0004 שהוציא לרשות הרבים בשני מקומות הנבדלים זה מזה — \u0003פטור.\u0004","\u0003ואמר רבה: ו\u0004מה שמחלק לענין זה רשות אחת לשתי רשויות \u0003הוא, שיש חיוב חטאת ביניהם,\u0004 שבין שני חלקי רשות הרבים היתה רשות היחיד, שהמוציא ממנה בשוגג לרשות הרבים או להיפך — חייב חטאת, \u0003אבל כרמלית\u0004 (רשות ממוצעת, שאינה רשות רבים ולא רשות יחיד), והוא מקום שאסור להוציא אליו רק מדברי סופרים — \u0003לא. אביי אמר: אפילו כרמלית\u0004 מחלקת, \u0003אבל פיסלא\u0004 (בול עץ) — \u0003לא. רבא אמר: אפילו פיסלא\u0004 מחלק לענין זה את רשות הרבים, שהרי זה כמצר וחצב שמבדילים בין שדות שונים.","\u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: רשות שבת כרשות גיטין דמי\u0004 \u0005[\u0006היא \u0005נחשבת].\u0006 וכשם שלהלכות גיטין פיסלא נחשב כמקום נפרד, אף לענין הפרדה ברשות שבת כן.","ושואלים: \u0003אין שם לא מצר ולא חצב, מאי\u0004 \u0005[מה]\u0006 הגבול של השדה שקונה אותו? \u0003פירש ר' מרינוס משמו\u0004 של ר' יוחנן: \u0003כל שנקראת על שמו.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[מה פירוש הדבר]\u0006 כל שנקראת על שמו? \u0003אמר רב פפא: דקרו ליה בי גרגותא דפלניא\u0004 \u0005[שקורים לו מקום\u0006 שמשקים מ\u0005בור של פלוני]\u0006 וכל אותו מקום שנקרא כן הוא שדה אחד.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אחא בר עויא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אסי, ויתיב וקאמר משמיה\u0004 \u0005[וישב והיה אומר משמו]\u0006 של \u0003ר' אסי בר חנינא: חצובא\u0004 \u0005[החצב]\u0006 \u0003מפסיק בנכסי הגר,\u0004 שאם יש שורה של חצבים באמצע הרי זו מפסיקה, שכל חלק יחשב לשדה לעצמו.","ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 הוא\u0005]\u0006 \u0003חצובא? אמר רב יהודה אמר רב: שבו תיחם יהושע לישראל את הארץ\u0004 שקבע תחום כל נחלה ונחלה.","אגב כך מביאים עוד מסורת של רב יהודה בשם רב בענין קרוב, \u0003ואמר רב יהודה אמר רב: לא מנה יהושע\u0004 בספרו \u0003אלא עיירות העומדות על הגבולין,\u0004 אבל לא את כל הערים שהיו בתחומו של כל שבט.","ועוד בענין של תחומי הארץ, \u0003אמר רב יהודה אמר שמואל: כל\u0004 המקומות \u0003שהראהו הקדוש ברוך הוא למשה\u0004 לפני מותו, שנאמר \"ויראהו ה' את כל הארץ את הגלעד... עד צוער\" (דברים לד, א– ג) — \u0003חייב במעשר,\u0004 שהם בתחומי ארץ ישראל.","ושואלים: \u0003לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]?\u0006 מה רצה להוציא, שאינו נכלל בתחום זה? ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 את ארץ \u0003קיני, קניזי, וקדמוני\u0004 שהבטיח ה' לאברהם בברית בין הבתרים \"לזרעך נתתי את הארץ הזאת... את הקיני ואת הקנזי ואת הקדמוני\" (בראשית טו, יח – יט). ומה הם? — \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר:\u0004 הרי זה \u0003נפתוחא, ערבאה, ושלמאה. ר' יהודה אומר:\u0004 אלה הם \u0003הר שעיר, עמון, ומואב. רבי שמעון אומר:\u0004 הרי הם \u0003ערדיסקיס, אסיא\u0004 הקטנה, \u0003ואספמיא.\u0004","\u0003היו שנים,\u0004 שני עדים, \u0003מעידין אותו\u0004 את המחזיק בשדה \u0003שאכלה שלש שנים\u0004 ויש לו איפוא חזקה, \u0003ונמצאו\u0004 שהם עדים \u0003זוממים\u0004 שהוכח שלא ראו דבר זה — \u0003משלמין לו\u0004 לבעל השדה \u0003את הכל,\u0004 כל מה שרצו להפסידו בעדותם (כנאמר \"ועשיתם לו כאשר זמם לעשות לאחיו\". דברים יט, יט). אם היו \u0003שנים\u0004 מעידים שאכל מן השדה \u0003ב\u0004שנה \u0003ראשונה,\u0004 ו\u0003שנים\u0004 אחרים מעידים שאכל \u0003ב\u0004שנה ה\u0003שני\u0004 \u0003ה, ושנים\u0004 מעידים \u0003ב\u0004שנה ה\u0003שלישית,\u0004 ונמצאו כולם עדים זוממים —"],["\u0003משלשין\u0004 (מחלקים) \u0003ביניהם\u0004 את תשלום דמי השדה.","\u0003שלשה אחים\u0004 שכל אחד מהם מעיד על שנה אחת של חזקה בשדה, \u0003ואחד מצטרף עמהם\u0004 עם כל אחד מהאחים, להעיד — \u0003הרי אלו שלש עדיות\u0004 נפרדות, ואין האחים נחשבים כמעידים יחד ונפסול משום כך את העדות, \u0003ו\u0004אולם \u0003הן עדות אחת ל\u0004ענין \u0003הזמה,\u0004 שאין אומרים שהם כשלוש עדויות נבדלות, אלא כעדות אחת, בגלל האיש שמצרף אותם.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' עקיבא\u0004 היא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: כשהלך אבא חלפתא\u0004 (אביו של ר' יוסי) \u0003אצל ר' יוחנן בן נורי ללמוד תורה, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 כשהלך \u0003ר' יוחנן בן נורי אצל אבא חלפתא ללמוד תורה, אמר לו: הרי שאכלה שנה ראשונה בפני שנים,\u0004 שנה \u0003שניה בפני שנים\u0004 אחרים, \u0003שלישית בפני שנים, מהו\u0004 הדין בכגון זה? \u0003אמר לו: הרי זו חזקה.\u0004","\u0003אמר לו: אף אני אומר כן\u0004 שחזקה היא, \u0003אלא שר' עקיבא חולק בדבר זה, שהיה ר' עקיבא אומר:\u0004 העדים מעידים על \u0003\"דבר\"\u0004 (\"על פי שנים עדים או על פי שלשה עדים יקום דבר\". דברים יט, טו) \u0003ולא\u0004 על \u0003חצי דבר.\u0004 שהעדים צריכים להעיד עדות על ענין שלם. וכאן, כיון שהחזקה מתבססת על עדות של שלוש שנים, נמצא שכל אחד מהם אינו מעיד עדות על דבר שלם.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' עקיבא \u0003האי\u0004 \u0005[זה]\u0006 הלימוד של \u0003\"דבר\" ולא חצי דבר, מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו],\u0006 איזה מיעוט לומדים הם ממנו? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 מקרה שמעידים שנים על נערה שיש לה שתי שערות וכבר בגרה, \u0003אחד אומר\u0004 שיש שערה \u0003אחת בגבה, ואחד אומר\u0004 שיש שערה \u0003אחת בכריסה,\u0004 ואומרים חכמים שאין זו נחשבת לעדות, משום שהם מעידים על חצי דבר. ואולם \u0003האי\u0004 \u0005[\u0006מקרה \u0005זה]\u0006 גם \u0003חצי דבר ו\u0004גם \u0003חצי עדות היא,\u0004 שהרי אפילו על חצי הדבר אין כאן עדות שלימה של שני עדים, ועדות כזו בוודאי פסולה לדברי הכל!","\u0003אלא\u0004 לדעת חכמים בא \"דבר ולא חצי דבר\" \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרה שבו \u0003שנים אומרים \"\u0004שערה \u0003אחת בגבה\", ושנים אומרים \"\u0004שערה \u0003אחת בכרסה\",\u0004 שכל אחת מכתות העדים היא עדות שלימה, אבל רק על חצי דבר — על שערה אחת בלבד.","ובענין דומה למשנתנו \u0003אמר רב יהודה:\u0004 שני עדים שהעידו על אדם שהחזיק בשדה שלוש שנים, עד \u0003אחד אומר אכלה חטים, ואחד אומר אכלה שעורים\u0004 — \u0003הרי זו חזקה. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: אלא מעתה, אחד אומר אכלה\u0004 שנה \u0003ראשונה\u0004 ו\u0003שלישית וחמישית, ואחד אומר אכלה שניה\u0004 ו\u0003רביעית וששית, הכי נמי דהויא\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שתהיה\u0006 זו\u0005]\u0006 \u0003חזקה?\u0004 והרי הם מעידים על שני דברים שונים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה: הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם בשתא דקא מסהיד מר\u0004 \u0005[שם,\u0006 בדוגמא שהבאת, \u0005בשנה שמעיד זה]\u0006 \u0003לא קא מסהיד מר\u0004 \u0005[מעיד זה],\u0006 שהם מעידים על שנים שונות, וממילא על מאורעות שונים. \u0003הכא תרוייהו בחדא שתא קא מסהדי\u0004 \u0005[כאן שניהם בשנה אחת הם מעידים].\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שיש סתירה בעדותם \u0003בין חיטי לשערי\u0004 \u0005[חיטים לשעורים]?\u0006 \u0003לאו אדעתייהו דאינשי\u0004 \u0005[אין\u0006 זה \u0005על דעתם של אנשים]\u0006 להקפיד ולדקדק בכך, ועל כל פנים שנים מעידים שהשתמש בשדה שלוש שנים.","שנינו במשנה שעדות של \u0003שלשה אחין ואחד מצטרף עמהן\u0004 — \u0003הרי אלו שלש עדיות, והן עדות אחת להזמה.\u0004"],["מסופר: \u0003ההוא שטרא דהוה חתימי עליה בי תרי\u0004 \u0005[שטר אחד שהיו חתומים עליו שנים].\u0006 \u0003שכיב חד מינייהו\u0004 \u0005[מת אחד מהם,\u0006 מן העדים\u0005],\u0006 והלכו לבית הדין לקיים את השטר, ודבר זה נעשה כשהעד עצמו או שני אנשים אחרים מעידים שזו היא חתימתו. \u0003אתא אחוה דהאי דקאי, וחד אחרינא, לאסהודי אחתימת ידיה דאידך\u0004 \u0005[בא אחיו של זה,\u0006 של העד \u0005שקיים\u0006 חי, \u0005ו\u0006עוד אדם \u0005אחר, להעיד על חתימת ידו של האחר\u0006 שמת\u0005],\u0006 והעד החי העיד על חתימתו שלו.","\u0003סבר\u0004 \u0005[סבור]\u0006 היה \u0003רבינא למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו מתניתין\u0004 \u0005[זהו\u0006 דין \u0005משנתנו]:\u0006 \u0003שלשה אחין\u0004 שמעיד כל אחד מהם על אכילת שנה אחרת \u0003ואחד מצטרף עמהן\u0004 — הרי אלו שלוש עדויות. שאף כאן, האח האחד מעיד לקיים חתימת ידו שלו, והאח השני מעיד על חתימתו של זה שמת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם לא נפיק נכי ריבעא דממונא אפומא דאחי\u0004 \u0005[שם אין יוצא\u0006 כל \u0005הממון פחות רבע\u0006 מאדם לחבירו \u0005על פי\u0006 עדות \u0005האחים],\u0006 אלא רק חצי הממון, שכל אחד מן האחים מהווה חצי עדות על השנה שמעיד עליה. \u0003הכא נפיק נכי ריבעא דממונא אפומא דאחי\u0004 \u0005[כאן יוצא\u0006 כל \u0005הממון פחות רבע על פי האחים]\u0006 כי אח אחד מעיד על חתימתו שהיא מחצית העדות, ולגבי החתימה השניה אחיו שותף עם האחר, ונמצא ששלושת רבעי העדות תלויה בקרובים, ועדות זו פסולה.","\u0003אלו דברים שיש להן חזקה\u0004 על ידי שמשתמש בהם, \u0003ואלו דברים שאין להן חזקה\u0004 שאי אפשר לומר שיש לו חזקה לגביהם, כיצד? אם \u0003היה מעמיד בהמה בחצר,\u0004 או מעמיד שם \u0003תנור,\u0004 או \u0003ריחים וכיריים, ו\u0004כן אם היה \u0003מגדל תרנגולים\u0004 בחצר, או \u0003נותן זבלו בחצר\u0004 — \u0003אינה חזקה. אבל\u0004 אם \u0003עשה מחיצה לבהמתו גבוה עשרה טפחים, וכן לתנור וכן לכיריים וכן לריחים,\u0004 או \u0003הכניס תרנגולין לתוך הבית, ו\u0004כן אם \u0003עשה\u0004 לו \u0003מקום לזבלו\u0004 שהיה \u0003עמוק שלשה\u0004 טפחים מן הקרקע \u0003או גבוה\u0004 ממנה \u0003שלשה\u0004 — \u0003הרי זו חזקה.\u0004","ושואלים: \u0003מאי שנא רישא\u0004 \u0005[במה שונה ההתחלה]\u0006 שבהעמדת בהמה בחצר אין לו חזקה, \u0003ומאי שנא סיפא\u0004 \u0005[ובמה שונה הסוף]\u0006 שאם עשה לבהמתו מחיצה הרי זו חזקה?","\u0003אמר עולא: כל\u0004 מעשה של קנין \u0003שאילו\u0004 היה נעשה \u0003בנכסי הגר קנה\u0004 — גם אם עושה כן \u0003בנכסי חבירו קנה\u0004 בחזקה של שלוש שנים, כשטוען שקנה ממנו את הקרקע. \u0003כל שאילו בנכסי הגר לא קנה\u0004 — אף \u0003בנכסי חבירו לא קנה.\u0004 ודווקא מעשה שיש בו משום תיקון ומעשה בגוף הנכס, כגון העמדת מחיצה, הריהו קונה בנכסי הגר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: וכללא\u0004 \u0005[ו\u0006כי \u0005כלל]\u0006 \u0003הוא? והרי ניר\u0004 (חרישה) ש\u0003בנכסי הגר קנה\u0004 בכך, ואילו \u0003בנכסי חבירו לא קנה!\u0004 ומן הצד השני, \u0003והרי אכילת פירות\u0004 במשך שלוש שנים, ש\u0003בנכסי חבירו קנה\u0004 בכך חזקה, ואילו \u0003בנכסי הגר לא קנה,\u0004 ואם כן בטל הכלל!","\u0003אלא אמר רב נחמן אמר רבה בר אבוה:\u0004"],["\u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בחצר השותפין עסקינן\u0004 \u0005[אנו עוסקים],\u0006 שעל \u0003העמדה כדי לא קפדי\u0004 \u0005[בלבד אינם מקפידים]\u0006 זה על זה, ולכן אינו קונה חזקה בהעמדת הבהמה, התנור וכו', בחצר המשותפת אפילו במשך זמן רב, ואילו על \u0003מחיצה קפדי\u0004 \u0005[מקפידים]\u0006 ואם בנה השותף מחיצה ולא מחה בו —","ברשות עשה. ושואלים: \u0003ובהעמדה כדי לא קפדי\u0004 \u0005[בלבד אינם מקפידים]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003השותפין שנדרו הנאה זה מזה\u0004 — \u0003אסורין ליכנס לחצר\u0004 המשותפת, משמע שיש הקפדה אפילו במעבר בחצר השותפים, וכל שכן בהעמדת בהמה או חפצים!","\u0003אלא אמר רב נחמן אמר רבה בר אבוה: הכא\u0004 \u0005[כאן]\u0006 \u0003ברחבה של אחורי בתים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ש\u0003העמדה כדי\u0004 \u0005[בלבד]\u0006 \u0003לא קפדי\u0004 \u0005[מקפידים],\u0006 \u0003ו\u0004על \u0003מחיצה קפדי\u0004 \u0005[מקפידים].\u0006","ואילו \u0003רב פפא אמר: אידי ואידי\u0004 \u0005[זה וזה],\u0006 גם לענין נדרים וגם במשנתנו, מדובר \u0003בחצר השותפין, ואיכא דקפדי ואיכא דלא קפדי\u0004 \u0005[ויש המקפידים\u0006 על העמדה, ואף על מעבר בחצר, \u0005ויש שאינם מקפידים],\u0006 \u0003גבי ממונא לקולא\u0004 \u0005[אצל\u0006 דיני \u0005ממונות\u0006 הולכים \u0005להקל],\u0006 ואנו מניחים כי שותף אינו מקפיד על העמדה, ואולם \u0003גבי איסורא לחומרא\u0004 \u0005[אצל איסור\u0006 הולכים \u0005להחמיר]\u0006 כיוון שיש בכך ספק של עבירה לבעל הנדר.","\u0003רבינא אמר: לעולם לא קפדי\u0004 \u0005[אין מקפידים]\u0006 על העמדה, \u0003והא\u0004 \u0005[וזו]\u0006 המשנה בענין מודרי הנאה, \u0003מני\u0004 \u0005[מיהי]\u0006 שיטת \u0003ר' אליעזר היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אפילו ויתור אסור במודר הנאה,\u0004 שאף בדבר שכרגיל אנשים מוותרים ואינם מקפידים בו, כיוון שהדירו הנאה —","אסור לוותר, ולכן אף שכרגיל אין מקפידים בדריסת הרגל, סבור ר' אליעזר שהמודר הנאה אסור. \u0003אמר ר' יוחנן\u0004 \u0003משום\u0004 (בשם) \u0003ר' בנאה: בכל שותפין מעכבין זה את זה\u0004 מלהשתמש בחצר המשותפת, \u0003חוץ מן הכביסה\u0004 שאינם יכולים לעכב, \u0003שאין דרכן של בנות ישראל להתבזות על הכביסה,\u0004 ולכן צריך להרשות להן לכבס בתוך החצר, ולא להכריח אותן לכבס בחוץ במקום הגלוי לרבים.","אגב כך מביאים את הכתוב: \u0003\"ועצם עיניו מראות ברע\"\u0004 (ישעיהו לג, טו), \u0003אמר ר' חייא בר אבא: זה שאין\u0004 הולך בנהר ו\u0003מסתכל בנשים בשעה שעומדות על הכביסה,\u0004 שכיון שהן נמצאות במים הן מרימות את שולי בגדיהן, על מנת שלא יירטבו.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 מהו השבח הגדול בענין זה? \u0003אי דאיכא דרכא אחריתא\u0004 \u0005[אם שיש דרך אחרת]\u0006 ללכת בה — הלא \u0003רשע הוא\u0004 אם הולך הוא מתחילה בדרך זו, \u0003אי דליכא דרכא אחריתא\u0004 \u0005[אם שאין דרך אחרת]\u0006 — הלא \u0003אנוס הוא!\u0004 ומשיבים: \u0003לעולם\u0004 מדובר באופן \u0003דליכא דרכא אחריתא\u0004 \u0005[שאין דרך אחרת],\u0006 \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003מיבעי ליה למינס נפשיה\u0004 \u0005[צריך הוא לאנוס\u0006 את \u0005עצמו]\u0006 שיסב עיניו מן הנשים שלא להסתכל.","כיון שהוזכרו דברי ר' יוחנן בשם ר' בנאה, מביאים דבר נוסף שקיבל ר' יוחנן ממנו. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוחנן מר' בנאה: חלוק\u0004 בגד תחתון \u0003של תלמיד חכם כיצד?\u0004 אמר לו: \u0003כל שאין בשרו נראה מתחתיו\u0004 מתחת החלוק. ועוד שאלו: \u0003טלית של תלמיד חכם כיצד?\u0004 ענה לו: \u0003כל שאין חלוקו נראה מתחתיו טפח.\u0004 ועוד שאל: \u0003שלחן של תלמיד חכם כיצד?\u0004 אמר לו: \u0003שני שלישי גדיל,\u0004 שני שלישים של השלחן מכוסים במפה, \u0003ושליש גלאי\u0004 (מגולה). \u0003ועליו\u0004 על השליש המגולה, נמצאות \u0003קערות ו\u0004נמצא ה\u0003ירק. וטבעתו\u0004 של השולחן שבו היו נוטלים אותו, תהיה \u0003מבחוץ,\u0004 לא בצד הפונה כלפי האדם האוכל.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טבעתו מבפנים!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא דאיכא ינוקא\u0004 \u0005[זה שיש ילד\u0006 במקום\u0005],\u0006 שבכגון זה הטבעת מבחוץ, כדי שהילד לא ישחק בטבעת ויזיז או יהפוך את השולחן, \u0003הא דליכא ינוקא\u0004 \u0005[זה שאין ילד]\u0006 ואז הטבעת מבפנים.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003הא והא דליכא ינוקא\u0004 \u0005[זה וזה שאין\u0006 שם \u0005תינוק],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה];\u0006 \u0003הא דאיכא שמעא\u0004 \u0005[זה שיש שמש],\u0006 אז תהיה הטבעת מבפנים, כדי שלא ייכשל בה השמש, \u0003הא דליכא שמעא\u0004 \u0005[זה שאין שמש]\u0006 ואז הטבעת מבחוץ.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003הא והא דאיכא שמעא\u0004 \u0005[זה וזה שיש שמש],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא ביממא\u0004 \u0005[זה ביום]\u0006 שהשמש רואה את הטבעת, ונזהר ממנה, \u0003הא בליליא\u0004 \u0005[זה בלילה].\u0006 עד כאן שולחנו של תלמיד חכם.","\u0003ו\u0004שולחן \u0003של עם הארץ דומה\u0004"],["\u0003למדורה,\u0004 שהאש נמצאת באמצע \u0003וקדרות מקיפות אותה\u0004 ואף כאן, האוכל נמצא באמצע והקערות מסביב.","ועוד שאלו ר' יוחנן: \u0003מטה של תלמידי חכמים כיצד?\u0004 ענה לו ר' בנאה: \u0003כל שאין תחתיה אלא סנדלין בימות החמה ומנעלין בימות הגשמים\u0004 ולא יותר. \u0003ושל עם הארץ\u0004 — \u0003דומה לאוצר בלוס,\u0004 שמניח תחתיה תערובת דברים רבים.","כיון שהוזכר ר' בנאה מספרים כמה מעשים שאירעו בו, \u0003ר' בנאה הוה קא מציין מערתא\u0004 \u0005[היה מציין,\u0006 מסמן \u0005מערות\u0006 קבורה\u0005]\u0006 כדי לסמנן שלא ייטמאו על ידן. \u0003כי מטא למערתא\u0004 \u0005[כאשר הגיע למערה]\u0006 של \u0003אברהם\u0004 אבינו (מערת המכפלה), \u0003אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003אליעזר עבד אברהם דקאי קמי בבא\u0004 \u0005[שעומד לפני הפתח].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי קא עביד\u0004 \u0005[מה עושה]\u0006 \u0003אברהם\u0004 כעת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליעזר: \u0003גאני\u0004 \u0005[שוכב]\u0006 \u0003בכנפה\u0004 (בחיקה) של \u0003שרה וקא מעיינא ליה ברישיה\u0004 \u0005[והיא מעיינת,\u0006 בודקת \u0005בראשו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' בנאה: \u0003זיל אימא ליה\u0004 \u0005[לך אמור לו]\u0006 \u0003בנאה קאי אבבא\u0004 \u0005[עומד על הפתח].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ליעול\u0004 \u0005[שייכנס],\u0006 הרי \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 ש\u0003יצר בהאי עלמא ליכא\u0004 \u0005[\u0006\u0005בעולם הזה,\u0006 בעולם העליון, \u0005אין]\u0006 ולכן יכול הוא להיכנס, למרות שבעולם הזה אין נוהגים כך. \u0003עייל, עיין\u0004 \u0005[נכנס, עיין],\u0006 בחן את המערה כדי למדוד אותה, \u0003ונפק\u0004 \u0005[ויצא].\u0006","\u0003כי מטא למערתא\u0004 \u0005[כאשר הגיע למערתו]\u0006 של \u0003אדם הראשון,\u0004 שאף הוא קבור באותו מקום, \u0003יצתה בת קול ואמרה: נסתכלת בדמות דיוקני,\u0004 כלומר, הסתכלת באברהם שהוא כעין דמותו של אדם הראשון, \u0003בדיוקני\u0004 (בתמונתי) \u0003עצמה אל תסתכל,\u0004 שהרי נאמר שבצלם אלוקים עשה את האדם. אמר ר' בנאה: \u0003הא בעינא לציוני מערתא\u0004 \u0005[הרי צריך אני לציין\u0006 את \u0005המערה]!\u0006 אמרו לו: \u0003כמדת\u0004 המערה \u0003החיצונה\u0004 שם קבור אברהם \u0003כך מדת הפנימית.\u0004 ומעירים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שמערת המכפלה בנויה היתה \u0003שני בתים זו למעלה מזו,\u0004 אמרו לו ש\u0003כמדת\u0004 ה\u0003עליונה כך מדת התחתונה\u0004 ואין אתה צריך לבדוק יותר.","\u0003אמר ר' בנאה: נסתכלתי בשני עקיביו\u0004 של אדם הראשון, \u0003ו\u0004היו \u0003דומים לשני גלגלי חמה,\u0004 שכל כך היו זוהרים ומאירים. ובענין זה מביאים: \u0003הכל בפני שרה כקוף בפני אדם,\u0004 שהיתה יפה כל כך. ואולם \u0003שרה בפני חוה\u0004 — \u0003כקוף בפני אדם, חוה בפני אדם\u0004 — \u0003כקוף בפני אדם, אדם בפני שכינה\u0004 — \u0003כקוף בפני אדם.\u0004","ועוד אמרו: \u0003שופריה\u0004 \u0005[יופיו]\u0006 של \u0003רב כהנא\u0004 היה \u0003מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003רב, שופריה\u0004 \u0005[יופיו]\u0006 של \u0003רב מעין\u0004 \u0003שופריה\u0004 \u0005[יופיו]\u0006 של \u0003ר' אבהו, שופריה\u0004 \u0005[יופיו]\u0006 של \u0003ר' אבהו מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003יעקב אבינו,\u0004 ו\u0003שופריה\u0004 \u0005[יופיו]\u0006 של \u0003יעקב אבינו מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003אדם הראשון.\u0004","עוד מסופר: \u0003ההוא אמגושא דהוה חטיט שכבי\u0004 \u0005[\u0006היה \u0005אמגוש אחד שהיה מחטט\u0006 את \u0005המתים]\u0006 להוציא אותם מקברותיהם. \u0003כי מטא אמערתא\u0004 \u0005[כאשר הגיע למערת\u0006 הקבר\u0005]\u0006 של \u0003רב טובי בר מתנה תפשיה בדיקניה\u0004 \u0005[תפס אותו\u0006 רב טובי \u0005בזקנו]\u0006 ולא הניח לו. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003במטותא מינך, שבקיה\u0004 \u0005[בבקשה ממך, הנח לו].\u0006 \u0003לשנה אחריתי הדר אתא, תפשיה בדיקניה\u0004 \u0005[לשנה האחרת חזר\u0006 ו\u0005בא, תפס אותו\u0006 שוב \u0005בזקנו].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אביי\u0004 וביקש לשחררו, \u0003לא שבקיה\u0004 \u0005[הניחו]\u0006 \u0003עד דאייתי מספרא וגזיא לדיקניה\u0004 \u0005[שהביא מספריים וגזר את זקנו].\u0006","ועוד מסופר על ר' בנאה, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 בצוואה: \u0003חביתא דעפרא לחד בראי\u0004 \u0005[חבית של עפר לבני האחד],\u0006 \u0003חביתא דגרמי לחד בראי\u0004 \u0005[חבית של עצמות לבני האחד],\u0006 \u0003חביתא דאודרא לחד בראי\u0004 \u0005[חבית של מוך לבני האחד].\u0006 \u0003לא הוו ידעי מאי קאמר להו\u0004 \u0005[היו יודעים מה הוא אומר להם].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' בנאה\u0004 לשאול. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אית לכו ארעא\u0004 \u0005[יש לכם קרקע]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 והמשיך לשאול: \u0003אית לכו חיותא\u0004 \u0005[יש לכם בהמות]?\u0006 אמרו לו: \u0003אין\u0004 \u0005[כן].\u0006 \u0003אית לכו בסתרקי\u0004 \u0005[יש לכם מצעות]?\u0006 אמרו לו: \u0003אין\u0004 \u0005[כן].\u0006 אמר להם: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003הכי קאמר לכו\u0004 \u0005[כך אמר לכם]:\u0006 שהוא נותן קרקע לבן אחד, בהמות לבן אחר, ומצעות לבן שלישי.","ועוד מסופר, \u0003ההוא גברא דשמעה לדביתהו דקא אמרה לברתה\u0004 \u0005[איש אחד שמע את אשתו שהיא אומרת לבתה]:\u0006 \u0003אמאי לא צניעת באיסורא\u0004 \u0005[מדוע אין את נחבאת\u0006 כשאת עושה דברים \u0005אסורים]?\u0006 \u0003הך איתתא\u0004 \u0005[אשה זו],\u0006 אני \u0003עשרה בני אית\u0004 \u0005[בנים יש]\u0006 \u0003לה, ולית\u0004 \u0005[ואין]\u0006 \u0003לי מאבוך\u0004 \u0005[מאביך]\u0006 \u0003אלא חד\u0004 \u0005[אחד]\u0006 ואיש אינו יודע על כך. ואף את צריכה להיזהר שלא ידעו בך אנשים. כיון שידע האיש שרק אחד מהילדים הוא שלו, \u0003כי שכיב\u0004 \u0005[כאשר מת],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כל נכסי לחד ברא\u0004 \u0005[לבן אחד].\u0006","\u0003לא ידעי להי מינייהו\u0004 \u0005[ידעו לאיזה מהם].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' בנאה. אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו חבוטו קברא דאבוכון\u0004 [\u0005לכו הכו את הקבר של אביכם\u0006] \u0003עד דקאי ומגלי לכו להי מינייכו שבקא\u0004 \u0005[שיעמוד ויגלה לכם למי מכם הניח]\u0006 את נכסיו. \u0003אזלו כולהו\u0004 \u0005[הלכו כולם],\u0006 \u0003ההוא דבריה הוה\u0004 \u0005[אותו שבנו היה]\u0006 \u0003לא אזל\u0004 \u0005[הלך].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' בנאה: \u0003כולהו נכסי דהאי\u0004 \u0005[כל הנכסים של זה]\u0006 שלא הלך. כעסו האחים האחרים, \u0003אזלו אכלו קורצא בי מלכא\u0004 \u0005[הלכו והלשינו בבית המלך],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003איכא גברא חד ביהודאי, דקא מפיק ממונא מאנשי\u0004 \u0005[יש איש אחד בין היהודים שמוציא ממון מאנשים]\u0006 \u0003בלא סהדי\u0004 \u0005[עדים]\u0006 \u0003ובלא מידי\u0004 \u0005[דבר].\u0006 \u0003אתיוהו חבשוהו\u0004 \u0005[הביאו אותו\u0006 ו\u0005אסרו אותו].\u0006","\u0003אזלא דביתהו\u0004 \u0005[הלכה אשתו]\u0006 \u0003אמרה להו\u0004 \u0005[להם]\u0006 לשומרים: \u0003עבדא חד הוה\u0004 \u0005[עבד אחד היה]\u0006 \u0003לי,\u0004 \u0003פסקו לרישיה, ופשטו למשכיה ואכלו בישריה\u0004 \u0005[חתכו את ראשו, ופשטו את עורו ואכלו את בשרו],\u0006 \u0003וקא מלו ביה מיא ומשקו ביה לחברייא\u0004 \u0005[והם ממלאים בו מים ומשקים בו לחברים],\u0006 \u0003ולא קא יהבי\u0004 \u0005[ואין נותנים]\u0006 \u0003לי\u0004 לא \u0003דמי\u0004 \u0005[דמיו,\u0006 מחירו\u0005]\u0006 \u0003ולא אגריה\u0004 \u0005[שכרו].\u0006","\u0003לא ידעי מאי קא אמרה להו\u0004 \u0005[ידעו מה היא אומרת להם].\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003ניתו לחכימא דיהודאי ולימא\u0004 \u0005[נקרא לחכם היהודים ויאמר\u0006 לנו\u0005]\u0006 מה פירוש הדבר. \u0003קריוהו\u0004 \u0005[קראוהו]\u0006 \u0003לר' בנאה, אמר להו\u0004 \u0005[להם]:\u0006 \u0003זרנוקא\u0004 \u0005[נאד]\u0006 \u0003אמרה לכו\u0004 \u0005[לכם],\u0006 התכוונה לתיש שהיה לה, ששחטוהו ואכלו את בשרו ועשו מעורו נאד למלא בו מים לשתיה. \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003הואיל וחכים כולי האי, ליתיב אבבא ונידון דינא\u0004 \u0005[ו\u0006הוא \u0005חכם כל כך, שישב על השער\u0006 במושב הדיינים, \u0005וידון דין].\u0006","\u0003חזא דהוה כתיב באבולא\u0004 \u0005[ראה שהיה כתוב על השער]\u0006 נוסח כזה: \u0003כל דיין דמתקרי\u0004 \u0005[שנקרא,\u0006 שנתבע\u0005]\u0006 \u0003לדין\u0004 — \u0003לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003דיין,\u0004 שהדיין צריך להיות למעלה מכל ביקורת. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אלא מעתה, אתא איניש\u0004 \u0003מעלמא\u0004 \u0005[יבוא אדם סתם]\u0006"],["\u0003ומזמין ליה לדינא\u0004 \u0005[ויזמין אותו לדין],\u0006 האם \u0003פסליה\u0004 \u0005[יפסלנו]\u0006 אף שיצא בדין זכאי? \u0003אלא\u0004 כך צריך לכתוב: \u0003כל דיין דמתקרי\u0004 \u0005[שנקרא]\u0006 \u0003לדין ומפקין מיניה ממונא\u0004 \u0005[ומוציאים ממנו ממון]\u0006 \u0003בדין\u0004 — \u0003לאו שמיה\u0004 \u0005[אין שמו]\u0006 \u0003דיין.\u0004 כששמעו כך \u0003כתבו הכי\u0004 \u0005[כך]\u0006 כתוספת לאותה כתובת: \u0003ברם סאבי דיהודאי אמרי\u0004 \u0005[אבל זקני היהודים אומרים]:\u0006 \u0003כל דיין דמתקרי\u0004 \u0005[שנקרא]\u0006 \u0003לדין ומפקין מיניה ממונא\u0004 \u0005[ומוציאים ממנו ממון]\u0006 \u0003בדין\u0004 — \u0003לאו שמיה\u0004 \u0005[אין שמו]\u0006 \u0003דיין.\u0004","ועוד \u0003חזא דכתיב\u0004 \u0005[ראה\u0006 ר' בנאה \u0005שכתוב\u0006 שם\u0005]:\u0006 \u0003בראש כל מותא אנא\u0004 \u0005[מוות אני]\u0006 \u0003דם\u0004 שמחמת יתר דם אנשים מתים, \u0003בראש כל חיין אנא חמר\u0004 \u0005[החיים אני היין],\u0006 שמה שמחייה אנשים הוא היין. אמר להם: \u0003אלא מעתה, דנפיל מאיגרא ומית\u0004 \u0005[\u0006מי \u0005שנופל מגג ומת],\u0006 \u0003ודנפיל מדיקלא ומית\u0004 \u0005[\u0006או \u0005שנופל מדקל ומת],\u0006 \u0003דמא קטליה\u0004 \u0005[\u0006האם \u0005דם הרג אותו]?\u0006 \u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003מן דדרכיה למימת\u0004 \u0005[מי שדרכו,\u0006 שהולך, \u0005למות],\u0006 האם \u0003משקו ליה חמרא וחיי\u0004 \u0005[משקים לו יין וחי]?\u0006 \u0003אלא הכי בעי למכתב\u0004 \u0005[כך צריך לכתוב]:\u0006 \u0003בראש כל מרעין אנא\u0004 \u0005[החוליים אני]\u0006 ה\u0003דם, בראש כל אסוון אנא חמר\u0004 \u0005[הרפואות אני יין].\u0006 \u0003כתבו הכי\u0004 \u0005[כך]\u0006 באותו מקום: \u0003ברם סאבי דיהודאי אמרי\u0004 \u0005[אבל זקני היהודים אומרים]:\u0006 \u0003בראש כל מרעין אנא דם\u0004 \u0005[החוליים אני]\u0006 ה\u0003דם,\u0004 \u0003בראש כל אסוון אנא חמר\u0004 \u0005[הרפואות אני היין],\u0006 \u0003באתר דלית חמר\u0004 \u0005[במקום שאין יין]\u0006 — \u0003תמן מתבעו סמנין\u0004 \u0005[שם צריכים תרופות].\u0006","ואגב סיפור זה מביאים מעשה אחר, \u0003כתיב אפיתחא\u0004 \u0005[כתוב\u0006 היה \u0005על פתח]\u0006 \u0003קפוטקיא:\u0004 \u0003\"אנפק, אנבג, אנטל\",\u0004 שכולם מידה אחת הם. \u0003ואיזהו אנטל? זהו רביעית של תורה.\u0004","\u0003המרזב\u0004 הקטן דרכו נשפכים מים מן הגג לחצר חבירו \u0003אין לו חזקה,\u0004 שאינו יכול לדרוש להמשיך ולהשתמש בו, כיון שאינו קבוע, שמזיזים אותו ממקום למקום, אבל \u0003יש למקומו חזקה,\u0004 כאשר יבואר בגמרא. \u0003המזחילה,\u0004 מרזב ארוך לאורך כל הגג, \u0003יש לה חזקה.\u0004","\u0003סולם המצרי\u0004 שהוא קטן ונייד \u0003אין לו חזקה\u0004 שיוכל להשאירו באותו מקום, \u0003ולצורי\u0004 שהוא סולם גדול וקבוע \u0003יש לו חזקה.\u0004","\u0003חלון המצרית\u0004 \u0003אין לה חזקה, ולצורית יש לה חזקה. איזו היא חלון המצרית? כל\u0004 שהוא קטן כל כך \u0003שאין ראשו של אדם יכול ליכנס לתוכה. ר' יהודה אומר\u0004 באופן אחר: \u0003אם יש לה מלבן\u0004 (מסגרת מסביב) לחלון, \u0003אף על פי שאין ראשו של אדם יכול ליכנס לתוכה\u0004 — \u0003הרי זו חזקה.\u0004","על לשון המשנה תוהים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"המרזב אין לו חזקה ויש למקומו חזקה\"? אמר רב יהודה אמר שמואל, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003המרזב אין לו חזקה\u0004 — \u0003מרוח אחת\u0004 מצד אחד של הגג, שיכול בעל החצר להזיז אותו ממקום למקום באותו צד, אבל \u0003יש למקומו חזקה\u0004 — \u0003משתי רוחות\u0004 שאין יכול להזיזו לצד אחר לגמרי.","\u0003ר' חנינא אמר:\u0004 כך צריך לפרש, \u0003המרזב אין לו חזקה\u0004 — \u0003שאם היה ארוך מקצרו\u0004 בעל החצר שלמטה, \u0003ויש למקומו חזקה,\u0004 לומר \u0003שאם בא\u0004 בעל החצר \u0003לעוקרו\u0004 ורוצה לבטל לגמרי את המרזב, \u0003אינו עוקרו.\u0004","\u0003רב ירמיה בר אבא אמר\u0004 באופן אחר: \u0003המרזב אין לו חזקה\u0004 — \u0003שאם רוצה לבנות תחתיו בונה\u0004 ואין בעל המרזב מעכב בעדו, אבל \u0003יש למקומו חזקה\u0004 — \u0003שאם בא לעוקרו\u0004 לגמרי \u0003אינו עוקרו.\u0004"],["\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 מרזב אין לו חזקה, אבל \u0003המזחילה יש לה חזקה; בשלמא למאן דאמר הנך תרתי\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאמרו שני הדברים הללו,\u0006 הראשונים\u0005]\u0006 שמואל ור' חנינא — \u0003שפיר\u0004 \u0005[יפה]\u0006 שאפשר להבין מדוע בניגוד למרזב, הרי למזחילה משום קביעותה יש חזקה, שאין מזיזים אותה ממקומה ואין מקצרים אותה.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 רב ירמיה בר אבא\u0005]\u0006 שמרזב אין לו חזקה משמעו \u0003שאם רצה לבנות תחתיו בונה, מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]?\u0006 מה איכפת לבעל המזחילה אם בעל החצר בונה תחתיה, ומדוע תהא לו זכות לעכבו?","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במזחילה של בנין עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהיא עשויה מאבנים, בדרך בנייה, ומחוברת לכותל, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל המזחילה: \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דתתרע אשיתאי\u0004 \u0005[שיתרועע כותלי]\u0006 על ידי הבנייה מתחתיו.","\u0003אמר רב יהודה אמר שמואל: צינור\u0004 שהיה \u0003מקלח מים לחצר חברו, ובא בעל הגג לסותמו\u0004 שאינו רוצה עוד שהמים יזרמו לשם, \u0003בעל החצר מעכב עליו, דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003כי היכי דאת\u0004 \u0005[כמו שאתה]\u0006 \u0003קנית לך חצר דידי\u0004 \u0005[שלי]\u0006 \u0003למשדא ביה מיא\u0004 \u0005[להשליך בה\u0006 את \u0005המים\u0006 שלך\u0005],\u0006 \u0003לדידי נמי קני לי מיא דאיגרך\u0004 \u0005[לי גם כן נקנו המים של גגך],\u0006 וכיון שאני רוצה להשתמש בהם אינך יכול לשנות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בענין זה עצמו, ש\u0003ר' אושעיא אמר: מעכב\u0004 בעל החצר, \u0003ר' חמא\u0004 אביו של ר' אושעיא, \u0003אמר: אינו מעכב. אזל שייליה\u0004 \u0005[הלך\u0006 ו\u0005שאל]\u0006 את \u0003ר' ביסא\u0004 אביו של ר' חמא, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מעכב.\u0004 ומעירים: \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רמי בר חמא\u0004 כתוב זה: \u0003\"והחוט המשלש לא במהרה ינתק\"\u0004 (קהלת ד, יב), \u0003זה ר' אושעיא בנו של ר' חמא בנו של ר' ביסא\u0004 שהיו שלושה דורות של חכמים שהכירו זה את זה ונשאו ונתנו זה עם זה בהלכה.","שנינו במשנה ש\u0003סולם המצרי אין לו חזקה.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003סולם המצרי? אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כל שאין לו ארבעה חווקין\u0004 (שלבים).","שנינו במשנה ש\u0003חלון המצרית אין לה חזקה כו'.\u0004 ושואלים: \u0003מאי שנא גבי\u0004 \u0005[מה שונה אצל]\u0006 \u0003סולם\u0004 המצרי ש\u0003לא מפרש\u0004 מהו, \u0003ומאי שנא גבי\u0004 \u0005[ומה שונה אצל]\u0006 \u0003חלון\u0004 ש\u0003מפרש\u0004 מה נקרא חלון המצרי? ומשיבים: \u0003משום דקא בעי איפלוגי\u0004 \u0005[שהוא רוצה להביא\u0006 את דעתו \u0005החולקת]\u0006 של \u0003ר' יהודה בסיפא\u0004 \u0005[בסוף]\u0006 שיש מחלוקת בהגדרתו של חלון המצרי, לכן היה צורך להגיד מהי הגדרתו של תנא קמא.","ובענין זה של חלון \u0003אמר ר' זירא: למטה מארבע אמות\u0004 — \u0003יש לו\u0004 לבעל החלון \u0003חזקה, ו\u0004לכן \u0003יכול\u0004 השכן מתחילה \u0003למחות, למעלה מארבע אמות\u0004 — \u0003אין לו חזקה, ואינו יכול למחות. ור' אילעא אמר: אפילו למעלה מארבע אמות\u0004 — \u0003אין לו חזקה, ויכול למחות.\u0004","ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שכאן בשאלה האם \u0003כופין על מדת סדום קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' זירא, \u0005סבור]:\u0006 \u0003כופין,\u0004 ולכן אין השכן יכול למחות, שאינו ניזק על ידי חלון גבוה זה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אילעא, \u0005סבור]:\u0006 \u0003אין כופין?\u0004","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003כופין\u0004 על מידת סדום, \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 שלדעת ר' אילעא אין זו מידת סדום, \u0003דאמר ליה\u0004 \u0005[שאומר לו\u0006 בעל החצר\u0005]:\u0006 \u0003זימנין דמותבת שרשיפא תותך, וקיימת וקא חזית\u0004 \u0005[פעמים שאתה מניח ספסל תחתיך ואתה עומד ורואה\u0006 מה שבתוך ביתי\u0005]\u0006 ולכן אני מעכב. מסופר על \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003ר' אמי\u0004 בשאלה בענין זה, \u0003שדריה לקמיה\u0004 \u0005[שלח אותו לפני]\u0006 \u0003ר' אבא בר ממל, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עביד ליה\u0004 \u0005[עשה לו]\u0006 \u0003כ\u0004דברי \u0003ר' אילעא,\u0004 שאפילו למעלה מארבע אמות יכול למחות.","ובענין שנחלקו במשנתנו, מה נחשב חלון שיש לו חזקה, \u0003אמר שמואל: ולאורה\u0004 אם עושה את החלון הזה כדי לעשות בו אור במקום חשוך, אין צורך שיהיה זה חלון גדול, אלא \u0003אפילו\u0004 חלון \u0003כל שהוא יש לו חזקה\u0004 ואם לא מחה השכן מתחילה אינו יכול לומר לבעל החלון שיסתום אותו.","\u0003הזיז,\u0004 בית שכותלו סמוך לחצר חבירו, והוציא בליטה מן הכותל לתוך חלל חצר חבירו, \u0003עד טפח\u0004 — \u0003יש לו חזקה,\u0004"],["\u0003ו\u0004מצד שני \u0003יכול למחות\u0004 בעל החצר מתחילה בבעל הגג, אם הוא רוצה להוציא זיז כזה. אבל אם הזיז \u0003פחות מטפח\u0004 — \u0003אין לו חזקה, ואין יכול למחות.\u0004","\u0003אמר ר' אסי אמר ר' מני, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יעקב אמר ר' מני:\u0004 אם \u0003החזיק ב\u0004זיז \u0003טפח\u0004 — \u0003החזיק בארבע.\u0004 ותוהים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 מפני מה זכאי להחזיק בארבע? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 אם \u0003החזיק\u0004 בזיז \u0003רוחב טפח במשך\u0004 (באורך) \u0003ארבע\u0004 טפחים, \u0003החזיק\u0004 גם להרחיב את זיזו \u0003ברוחב ארבע\u0004 טפחים.","שנינו במשנה: אם היה זיז \u0003פחות מטפח\u0004 — \u0003אין לו חזקה, ואינו יכול למחות. אמר רב הונא: לא שנו\u0004 שאינו יכול למחות \u0003אלא בעל הגג בבעל החצר,\u0004 שאינו יכול לומר לו שלא יעשה דבר המבטל את השימוש בזיז, \u0003אבל בעל החצר בבעל הגג יכול למחות\u0004 ולומר לו שלא יוציא זיז אף קטן מטפח, או שלא ישתמש בו, לפי שהוא מזיק לו בראיה. \u0003ורב יהודה אמר: אפילו בעל חצר בבעל הגג אינו יכול למחות.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003ב\u0004שאלה של \u0003היזק ראיה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 רב הונא \u0005סבור]:\u0006 \u0003שמיה\u0004 \u0005[שמו]\u0006 \u0003היזק,\u0004 ולכן יכול בעל החצר למחות, שמתוך שמשתמש בעל הגג בזיז — אף מביט בבעל החצר, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב יהודה, \u0005סבור]:\u0006 \u0003לאו שמיה\u0004 \u0005[אין שמו]\u0006 \u0003היזק?\u0004","ודוחים: \u0003לא,\u0004 יש לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 היזק ראיה \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003היזק, ו\u0004מדוע לדעת רב יהודה אין בעל החצר יכול למחות בבעל הגג? שכן \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הגג לבעל החצר: \u0003לתשמישתא לא חזי\u0004 \u0005[לתשמיש אין\u0006 הזיז \u0005ראוי],\u0006 שאי אפשר לעמוד עליו וכך להביט בו מפני שהוא קטן מדי, \u0003למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]?\u0006 — \u0003למתלא ביה מידי\u0004 \u0005[לתלות בו דבר]\u0006 ולא יותר, \u0003מהדרנא אפאי ותלינא ביה\u0004 \u0005[אחזיר\u0006 את \u0005פני ואתלה בו]\u0006 ולא אסתכל בחצרך.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 רב הונא, מדוע לשיטתו יכול בעל החצר למחות? משום ש\u0003אמר ליה\u0004 \u0005[יכול לומר לו]:\u0006 \u0003זימנין דבעיתת\u0004 \u0005[פעמים שאתה מפחד]\u0006 מפני שאתה עומד בראש הגג ותחזיר פניך ותסתכל.","\u0003לא יפתח אדם חלונותיו לחצר השותפין,\u0004 כלומר, לחצר שיש לו בה שותפות. אם \u0003לקח\u0004 (קנה) \u0003בית בחצר אחרת\u0004 הסמוכה לחצר זו — \u0003לא יפתחנה בחצר השותפין. בנה עלייה על גבי ביתו\u0004 — \u0003לא יפתחנה לחצר השותפין, אלא אם רצה\u0004 לבנות עליה, \u0003בונה את החדר לפנים מביתו, ובונה עלייה על גבי ביתו, ופותחה לתוך ביתו\u0004 ולא לתוך חצר השותפים.","על דין המשנה שאסור לו לאדם לפתוח חלונותיו לחצר שיש לו בה שותפות, שואלים: \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע נאסר הדבר דווקא \u0003לחצר השותפין? אפילו לחצר חבירו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יפתח, שהרי מזיק לו בראיה!","ומסבירים: בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר]\u0006 ובאופן זה: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003לחצר חברו\u0004 ש\u0003לא\u0004 התירו לו לפתוח חלון, שוודאי אינו רשאי להביט בחצירו. \u0003אבל לחצר השותפין דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 הפותח את החלון: \u0003סוף סוף הא קא בעית אצטנועי מינאי\u0004 \u0005[הרי\u0006 גם כך \u0005צריך אתה להצטנע ממני]\u0006 לנהוג צניעות \u0003בחצר,\u0004 שהרי אף אני שותף בחצר זו, ואם כן מה איכפת לך שאני פותח חלון לחצר? על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיכול השותף למחות בו, \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]:\u0006 \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 רק \u0003בחצר הוה בעינא אצטנועי מינך\u0004 \u0005[הייתי צריך להצטנע ממך]\u0006 שהיינו משתמשים בה יחד, \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003אפילו בבית נמי בעינא אצטנועי מינך\u0004 \u0005[גם כן צריך אני להצטנע ממך],\u0006 שהרי אתה יכול להביט גם בתוך ביתי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה באדם אחד שפתח חלוניו לחצר השותפין, ובא לפני ר' ישמעאל בר ר' יוסי, אמר לו: החזקת, בני, החזקת,\u0004 ואי אפשר עוד למחות בידך. \u0003ובא\u0004 אותו ענין \u0003לפני ר' חייא, אמר\u0004 לו: כמו ש\u0003יגעת ופתחת\u0004 חלון, כך \u0003יגע וסתום\u0004 שהדין עמם, שיכולים למחות בך.","\u0003אמר רב נחמן:\u0004"],["\u0003ולסתום,\u0004 אם חבירו סתם את החלון בפניו — \u0003לאלתר הוי\u0004 \u0005[מיד הריהי]\u0006 \u0003חזקה\u0004 שישאר סתום, משום \u0003שאין אדם עשוי שסותמים אורו בפניו ושותק,\u0004 ואם לא מחה מיד — משמע שהסותם נהג כדין, או שהלה מסכים.","שנינו במשנה: \u0003לקח בית בחצר אחרת\u0004 — \u0003לא יפתחנו לחצר השותפין.\u0004 מסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מפני שמרבה עליהם את הדרך,\u0004 שעכשיו יש אנשים נוספים הבאים מן הבית לחצר השותפים, ואין בעלי החצר רוצים שירבו בחצרם אנשים העוברים בה ומפריעים להם.","ומקשים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אלא אם רצה\u0004 — \u0003בונה את החדר לפנים מביתו, ובונה עלייה על גבי ביתו;\u0004 והרי גם בזה יש לומר אותו חשש: \u0003והלא מרבה עליו את הדרך! אמר רב הונא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חדר\u0004 שבנה? לא חדר חדש שהוסיף לביתו אלא שחדר \u0003ש\u0004קיים בביתו — \u0003חלקו בשנים\u0004 לשני חדרים, \u0003ו\u0004כן \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003עלייה\u0004 שאמרו? \u0003אפתאי\u0004 (קומה פנימית) שחילקו את החדר הקיים לגובה, ועשו בתוכו עליה.","\u0003לא יפתח אדם לחצר השותפין,\u0004 כלומר, חצר שיש לו בה שותפות, \u0003פתח כנגד פתח וחלון כנגד חלון,\u0004 כדי שלכל אדם תהא מידה של פרטיות וצינעה. \u0003היה\u0004 החלון \u0003קטן\u0004 — \u0003לא יעשנו גדול,\u0004 היה חלון \u0003אחד\u0004 — \u0003לא יעשנו שנים. אבל פותח הוא לרשות הרבים\u0004 אפילו \u0003פתח כנגד פתח וחלון כנגד חלון,\u0004 וכן אם \u0003היה\u0004 חלון \u0003קטן\u0004 — \u0003עושה אותו גדול, ו\u0004אם היה \u0003אחד\u0004 — \u0003עושה אותו שנים.\u0004","שואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאין פותחים פתח כנגד פתח או חלון כנגד חלון? \u0003אמר ר' יוחנן,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וישא בלעם את עיניו וירא את ישראל שכן לשבטיו\u0004 ותהי עליו רוח אלהים\u0003\"\u0004 (במדבר כד, ב). ומסבירים: \u0003מה ראה?\u0004 — \u0003ראה שאין פתחי אהליהם מכוונין זה לזה,\u0004 והתפעל מכך ו\u0003אמר:\u0004 כיון שכך \u0003ראוין הללו שתשרה עליהם שכינה.\u0004","שנינו במשנה: \u0003היה\u0004 החלון \u0003קטן\u0004 — \u0003לא יעשנו גדול. סבר\u0004 \u0005[חשב]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]\u0006 שפירוש הדבר הוא שפתח \u0003בר ארבעי\u0004 \u0005[בן ארבע]\u0006 אמות \u0003לא לישוייה בר\u0004 \u0003תמניא\u0004 \u0005[יעשה אותו בן שמונה],\u0006 משום \u0003דקא שקיל תמניא\u0004 \u0005[\u0006\u0005שהוא לוקח שמונה]\u0006 אמות כנגדם \u0003בחצר\u0004 בזכות הפתח הזה, שיש לו לאדם זכות שימוש בחצר ארבע אמות כנגד כל רוחב הפתח שלו. \u0003אבל\u0004 אם היה \u0003בר תרתי לישוייה בר ארבעי\u0004 \u0005[בן שתי\u0006 אמות \u0005לעשות אותו בן ארבע]\u0006 אמות — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר הדבר\u0005],\u0006 לפי שיש לכל פתח (גם אם הוא קטן) זכות לארבע אמות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מצי אמר ליה\u0004 \u0005[יכול\u0006 הוא \u0005לומר לו]:\u0006 \u0003בפיתחא זוטרא מצינא לאצטנועי מינך\u0004 \u0005[בפתח קטן\u0006 שלך \u0005יכול הייתי להצטנע,\u0006 לשמור על צניעות, \u0005ממך],\u0006 \u0003בפיתחא רבה לא מצינא אצטנועי מינך\u0004 \u0005[בפתח גדול אינני יכול להצטנע\u0006 לשמור על צניעות \u0005ממך].\u0006","עוד שנינו במשנה: היה לו פתח \u0003אחד\u0004 — \u0003לא יעשנו שנים.\u0004 ואף כאן \u0003סבר\u0004 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]:\u0006 פתח \u0003בר ארבעי\u0004 \u0005[בן ארבע]\u0006 אמות \u0003לא לישוייה תרי\u0004 \u0005[יעשה אותו שניים]\u0006 \u0003בני תרתי תרתי\u0004 \u0005[שתיים שתיים]\u0006 אמות, משום \u0003דקא שקיל תמני\u0004 \u0005[שהוא לוקח שמונה]\u0006 אמות \u0003בחצר,\u0004 ארבע אמות לכל פתח ופתח, \u0003אבל\u0004 פתח \u0003בר תמני לישוייה\u0004 \u0005[בן שמונה\u0006 אמות \u0005לעשות אותו\u0006 שניים\u0005]\u0006 \u0003בני ארבעי ארבעי\u0004 \u0005[ארבע ארבע]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר הדבר\u0005],\u0006 שהרי אינו נוטל יותר מן החצר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 השכן: \u0003בחד פיתחא מצינא אצטנועי מינך\u0004 \u0005[בפתח אחד\u0006 שלך \u0005יכול אני להצטנע ממך],\u0006 \u0003בתרי לא מצינא אצטנועי מינך\u0004 \u0005[בשניים אינני יכול להצטנע ממך],\u0006 שאינני יודע באיזה מהם אתה משתמש בכל פעם.","שנינו במשנה: \u0003אבל פותח הוא לרשות הרבים פתח כנגד פתח.\u0004 וטעמו של דבר — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לשכן שממול, שרוצה למנוע ממנו דבר זה: \u0003סוף סוף\u0004 בסופו של דבר \u0003הא בעית אצטנועי\u0004 \u0005[הרי צריך אתה להצטנע]\u0006 \u0003מבני רשות הרבים.\u0004 וכיון שאינך יכול לעכב אותם, ובהכרח אינך יכול לנהוג במקום זה מנהג צינעה, אם כן אף אינך יכול לעכב בפני מלפתוח פתח כנגדך.","\u0003אין עושין חלל תחת רשות הרבים\u0004 של \u0003בורות\u0004 ו\u0003שיחין\u0004 (חפירה מאורכת) \u0003ומערות\u0004 (חפירה מקורה). \u0003ר' אליעזר מתיר\u0004 שיעשה חלל כזה אם היה בנוי על גביו כיסוי חזק \u0003כדי שתהא עגלה מהלכת\u0004 עליו \u0003וטעונה אבנים\u0004 ולא ישבר, שהרי אין נזק יכול להיגרם על ידו. \u0003אין מוציאין זיזין וגזוזטראות לרשות הרבים, אלא אם רצה\u0004 לעשות זיז או גזוזטרה — \u0003כונס\u0004 את הכותל \u0003לתוך\u0004 התחום \u0003שלו ומוציא\u0004 זיזים וגזוזטראות עד גבול רשות הרבים. אם \u0003לקח\u0004 (קנה) \u0003חצר ובה זיזין וגזוזטראות\u0004 הבולטים לרשות הרבים — \u0003הרי זו בחזקתה\u0004 ואינו צריך להסיר אותם משם.","שואלים: הלא לכאורה יפה אמר ר' אליעזר, שאם הכיסוי על החלל הוא חזק דיו להחזיק עגלה טעונה אבנים יעשנו, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? ומשיבים: \u0003זימנין דמפחית ולאו אדעתיה\u0004 \u0005[פעמים שייפחת\u0006 הכיסוי הזה עם הזמן \u0005ולא יהיה בדעתו,\u0006 לא יבחין בדבר\u0005],\u0006 וייגרם מכשול לרבים\u0005.\u0006","שנינו במשנה: \u0003אין מוציאין זיזין וגזוזטראות\u0004 לרשות הרבים. מסופר: \u0003ר' אמי הוה ליה זיזא דהוה נפיק למבואה\u0004 \u0005[היה לו זיז שהיה יוצא למבוי]\u0006 \u0003וההוא גברא נמי הוה ליה זיזא דהוה מפיק\u0004 \u0005[ואדם אחד גם כן היה לו זיז\u0006 \u0005שהיה יוצא]\u0006 \u0003לרשות הרבים. הוו קא מעכבי עליה\u0004 \u0005[היו מעכבים עליו]\u0006 על אותו אדם \u0003בני רשות הרבים,\u0004 שהיו מוחים בו על שהוציא זיז המפריע לתנועה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל קוץ\u0004 \u0005[לך קצוץ\u0006 את הזיז שלך\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא מר נמי אית ליה\u0004 \u0005[והרי אדוני גם כן יש לו\u0006 זיז כזה\u0005]!\u0006 אמר לו ר' אמי: יש הבדל בין הדברים, \u0003דידי למבואה מפיק\u0004 \u0005[שלי למבוי\u0006 הוא \u0005יוצא],\u0006 ומכיון שדרים במבוי אנשים מסויימים יכול אני לומר לך כי \u0003בני מבואה מחלין גבאי\u0004 \u0005[המבוי מוחלים לי].\u0006 \u0003דידך\u0004 \u0005[שלך]\u0006 \u0003לרשות הרבים מפיק\u0004 \u0005[\u0006הוא \u0005יוצא],\u0006 \u0003מאן מחיל גבך\u0004 \u0005[\u0006ו\u0005מי מוחל לך]?\u0006 שהרי אין הדבר שייך לאנשים מסויימים אלא לציבור.","ועוד מסופר: \u0003ר' ינאי הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003אילן הנוטה לרשות הרבים, הוה ההוא גברא דהוה ליה נמי\u0004 \u0005[היה אדם אחד שהיה לו גם כן]\u0006 \u0003אילן הנוטה לרשות הרבים, אתו\u0004 \u0005[באו]\u0006 \u0003בני רשות הרבים הוו קא מעכבי עילויה\u0004 \u0005[\u0006ש\u0005היו מעכבים עליו,\u0006 על אותו אדם\u0005]\u0006 ודורשים שיקצוץ את האילן כמפורש במשנה (לעיל בבא בתרא כז,ב). \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' ינאי\u0004 להתדיין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי:"],["\u0003זיל האידנא ותא\u0004 \u0005[לך עכשיו ובוא]\u0006 \u0003למחר. בליליא שדר קצייה לההוא דידיה\u0004 \u0005[בלילה שלח\u0006 ר' ינאי \u0005וקצצו לאותו\u0006 אילן \u0005שלו]\u0006 שהיה יוצא לרשות הרבים.","\u0003למחר אתא לקמיה\u0004 \u0005[בא לפניו]\u0006 אותו איש, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003זיל קוץ\u0004 \u0005[לך קצוץ].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא מר נמי אית ליה\u0004 \u0005[הרי אדוני גם כן יש לו]\u0006 אילן הנוטה לרשות הרבים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל חזי\u0004 \u0005[לך\u0006 ו\u0005ראה],\u0006 \u0003אי קוץ דידי קוץ דידך\u0004 \u0005[אם קצוץ\u0006 האילן \u0005שלי קצוץ\u0006 את \u0005שלך],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא קוץ דידי\u0004 \u0005[קצוץ שלי]\u0006 \u0003לא תקוץ את\u0004 \u0005[תקצוץ אתה].\u0006","ושואלים: \u0003מעיקרא מאי סבר\u0004 \u0005[מתחילה מה חשב]\u0006 ר' ינאי \u0003ולבסוף מאי סבר\u0004 \u0005[מה חשב]?\u0006 שהרי רואים שבתחילה עשה זאת ולא חשש לנזק הרבים, ואחר כך קצץ את האילן. ומסבירים: \u0003מעיקרא סבר\u0004 \u0005[מתחילה חשב]:\u0006 \u0003ניחא להו\u0004 \u0005[נוח להם]\u0006 \u0003לבני רשות הרבים\u0004 באילן שלי, \u0003דיתבי בטוליה\u0004 \u0005[ש\u0006הם \u0005יושבים בצילו],\u0006 \u0003כיון דחזא דקא מעכבי\u0004 \u0005[שראה שהם מעכבים]\u0006 ומוחים באדם שיש לו אילן כזה, \u0003שדר קצייה\u0004 \u0005[שלח לקצץ אותו],\u0006 מפני שהבין שהוא מפריע לרבים. ושואלים: ומדוע שלח את אותו אדם שיחזור למחרת? \u0003ולימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003זיל קוץ דידך והדר אקוץ דידי\u0004 \u0005[לך קצוץ את\u0006 האילן \u0005שלך ואחר כך אקצוץ את שלי]!\u0006 ומשיבים: \u0003משום\u0004 דבריו של \u0003ריש לקיש,\u0004 ש\u0003אמר\u0004 הכתוב: \u0003\"התקוששו וקושו\"\u0004 (צפניה ב, א) יש לדורשו כך: \u0003קשוט,\u0004 קשט, תקן, \u0003עצמך\u0004 תחילה \u0003ואחר כך קשוט אחרים.\u0004","שנינו במשנה: אין מוציאים זיזים וגזוזטראות לרשות הרבים. \u0003אבל אם רצה\u0004 — \u0003כונס לתוך\u0004 התחום \u0003שלו ומוציא. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003כנס\u0004 את הכותל לתוך החצר שלו \u0003ולא הוציא\u0004 מיד, או לא נתעכב, \u0003מהו שיחזור ויוציא\u0004 לאחר זמן? \u0003ר' יוחנן אמר:\u0004 אם \u0003כנס\u0004 — \u0003מוציא\u0004 אף לאחר זמן. \u0003וריש לקיש אמר: כנס\u0004 ולא השתמש באפשרות לבנות — \u0003אינו מוציא\u0004 יותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא, אסברה\u0004 \u0005[אסביר]\u0006 \u0003לך\u0004 את הדבר: \u0003להוציא\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003מוציא,\u0004 שהרי בתוך שלו הוא מוציא, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — היה זה בשאלה האם מותר \u0003להחזיר כתלים למקומן,\u0004 שאם כנס לתוך רשותו, ונמלך שלא להוציא זיזים, האם מותר לו לחזור ולבנות את הגדר במקום, \u0003ואיפכא איתמר\u0004 \u0005[וההיפך נאמר]\u0006 במחלוקת זו, \u0003ר' יוחנן אמר: אינו מחזיר, וריש לקיש אמר: מחזיר.\u0004 וטעמם: \u0003ר' יוחנן אמר אינו מחזיר, משום\u0004 הדברים שאמר \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: מצר שהחזיקו בו רבים\u0004 ללכת בו \u0003אסור לקלקלו\u0004 שקנו לעצמם את זכות השימוש בו, אף שאינו רכוש הרבים. \u0003וריש לקיש אמר מחזיר,\u0004 מותר לו להחזיר, ומדוע? — \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 במצר, אמורים \u0003היכא דליכא רווחא\u0004 \u0005[במקום שאין רווח],\u0006 שאם יחזיר בעל המיצר לא יהא מקום לרבים ללכת. \u0003הכא הא איכא רווחא\u0004 \u0005[כאן,\u0006 במי שכנס לתוך שלו, \u0005הרי יש רווח]\u0006 של רשות הרבים.","","","שנינו במשנה: \u0003לקח\u0004 (קנה) \u0003חצר ובה זיזין וגזוזטראות\u0004 — \u0003הרי היא בחזקתה. אמר רב הונא: נפלה\u0004 חצר זו, שנתמוטטו כתליה — \u0003חוזר ובונה אותה\u0004 כפי שהיתה בתחילה על זיזיה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003אין מסיידין, ואין מכיירין\u0004 צורות בסיד, \u0003ואין מפייחין\u0004 (מציירים צורות בצבע) \u0003בזמן הזה\u0004 מפני אבילות המקדש. ואם \u0003לקח חצר\u0004 שהיתה \u0003מסוידת, מכוירת, מפויחת\u0004 — \u0003הרי זו בחזקתה\u0004 שנעשה הדבר בהיתר. אם \u0003נפלה\u0004 — \u0003אינו חוזר ובונה אותה\u0004 כדרך שהיתה בנויה בסיוד וכיור וכו'. משמע שאין לאדם רשות לחזור ולבנות בנין באופן שאסור לבנותו, אף שכשהיה בנוי עמד על חזקתו!","ומשיבים: דבר של \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003שאני\u0004 \u0005[שונה],\u0006 שהרי כאן הדבר הוא לא משום זכותם של אחרים, אלא משום האיסור שבדבר.","ובענין איסור זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יסוד אדם את ביתו בסיד, ואם עירב בו חול או תבן\u0004 — \u0003מותר,\u0004 לפי שאז אינו לבן ומבהיק כל כך. \u0003ר' יהודה אומר:\u0004 אם \u0003עירב בו חול\u0004 — \u0003הרי זה טרכסיד\u0004 (טיח סיד) ומשובח יותר מסיד סתם \u0003ואסור,\u0004 אבל אם עירב בו \u0003תבן\u0004 — \u0003מותר.\u0004 מאחר שהוזכרה ההלכה לגבי איסור סיוד בגלל אבילות החורבן, מביאים דברים נוספים בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשחרב הבית בשניה,\u0004 כלומר, בחורבן בית שני \u0003רבו פרושין בישראל ש\u0004נהגו לפרוש ו\u0003לא לאכול בשר ושלא לשתות יין. נטפל להן ר' יהושע, אמר להן: בני, מפני מה אי\u0004 \u0005[אין]\u0006 \u0003אתם אוכלין בשר ואין אתם שותין יין?\u0004 \u0003אמרו לו:\u0004 כיצד \u0003נאכל בשר, שממנו\u0004 היו \u0003מקריבין על גבי מזבח ועכשיו בטל?\u0004 וכיצד \u0003נשתה יין, שמנסכין\u0004 היו \u0003על גבי המזבח ועכשיו בטל?\u0004 \u0003אמר להם: אם כן, לחם\u0004 גם \u0003לא נאכל, שכבר בטלו מנחות\u0004 שהיו מקריבים על המזבח! אמרו לו: צודק אתה, ו\u0003אפשר\u0004 להסתפק \u0003בפירות.\u0004 אמר להם: אף \u0003פירות לא נאכל, שכבר בטלו בכורים!\u0004 אמרו לו: באמת נעשה כן, ולא נאכל מהפירות של שבעת המינים שמהם מביאים ביכורים, ש\u0003אפשר\u0004 להסתפק \u0003בפירות אחרים.\u0004 אמר להם: אם כן \u0003מים לא נשתה, שכבר בטל ניסוך המים! שתקו\u0004 שהבינו שאי אפשר לעמוד בכך.","\u0003אמר להן: בני, בואו ואומר לכם: שלא להתאבל כל עיקר אי אפשר\u0004 — לפי \u0003שכבר נגזרה גזרה\u0004 ונחרב הבית, \u0003ולהתאבל יותר מדאי\u0004 כפי שאתם עושים \u0003אי אפשר\u0004 גם כן — לפי \u0003שאין גוזרין גזירה על הצבור אלא אם כן רוב צבור יכולין לעמוד בה,\u0004 וראיה לדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במארה אתם נארים ואתי אתם קבעים הגוי כלו\"\u0004 (מלאכי ג, ט), לומר שרק על דבר שהגוי, העם, כולו קיבל על עצמו (במארה = בקללה) בא הנביא בטענה על שלא קיימוהו, ואם כולם אינם יכולים לעשות כן —","","","אין גוזרים גזירה בזה. \u0003אלא כך אמרו חכמים:\u0004 יעשה סימן לחורבן בכל דבר, ש\u0003סד אדם את ביתו בסיד, ומשייר בו דבר מועט\u0004 שאינו מסייד משום זכר לחורבן. ושואלים: \u0003וכמה\u0004 הוא דבר מועט? \u0003אמר רב יוסף: אמה על אמה\u0004 שאותה אינה מסייד. \u0003אמר רב חסדא:\u0004 ומשאיר את המקום הזה \u0003כנגד הפתח,\u0004 שיהא נראה לכל.","וממשיכה הברייתא, וכן אמרו חכמים: \u0003עושה אדם כל צרכי סעודה, ומשייר דבר מועט.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 דבר מועט זה? \u0003אמר רב פפא:\u0004 כגון \u0003כסא דהרסנא\u0004 (דגים קטנים מטוגנים) שאינו מביא אותם בתוך הסעודה, כדי שידעו שחסר משהו.","ומוסיפה הברייתא, וכן אמרו חכמים: \u0003עושה אשה כל תכשיטיה, ומשיירת דבר מועט.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 אותו דבר מועט? \u0003אמר רב: בת צדעא\u0004 מקום בצדע, ברקה, שהיו הנשים רגילות להוריד את השיער משם — אין מורידות, כדי שיהיה זכר לחורבן. וראיה לכל אלה — \u0003שנאמר: \"אם אשכחך ירושלם תשכח ימיני. תדבק לשוני לחכי\u0004 אם לא אזכרכי אם לא אעלה את ירושלים על ראש שמחתי \u0003\"\u0004(תהלים קלז, ה– ו). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005] \"\u0006\u0003על ראש שמחתי\"? אמר רב יצחק: זה אפר מקלה ש\u0004נוהגים להניח \u0003בראש חתנים\u0004 בשעת שמחת החופה, זכר לחורבן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: היכא מנח לה\u0004 \u0005[היכן מניחים אותו]?\u0006 אמר לו: \u0003במקום\u0004 שמניחים \u0003תפילין, שנאמר\u0004 בנבואות הנחמה: \u0003\"\u0004משח ה' אותי... שלחני... \u0003לשום לאבלי ציון לתת להם\u0004 \u0003פאר תחת אפר\"\u0004 (ישעיהו סא, א ושם פסוק ג. וכיון שתפילין קרויים \"פאר\" יש ללמוד מכאן שהאפר היה מונח במקום שמניחים בו תפילין.","","וממשיכה הברייתא: \u0003וכל המתאבל על ירושלים\u0004 — \u0003זוכה ורואה בשמחתה, שנאמר: \"שמחו את ירושלם\u0004 וגילו בה כל אוהביה, שישו אתה משוש כל המתאבלים עליה \u0003\"\u0004(ישעיהו סו, י). ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל בן אלישע: מיום שחרב בית המקדש, דין הוא שנגזור על עצמנו\u0004 מפני אבילות \u0003שלא לאכול בשר ולא לשתות יין, אלא\u0004 ש\u0003אין גוזרין גזרה על הצבור אלא אם כן רוב צבור יכולין לעמוד בה;\u0004","","\u0003ומיום שפשטה מלכות הרשעה,\u0004 מלכות רומי, \u0003שגוזרת עלינו גזירות רעות וקשות, ומבטלת ממנו תורה ומצות, ואין מנחת אותנו ליכנס לשבוע הבן,\u0004 כלומר, לברית המילה, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003לישוע הבן,\u0004 לפדיון הבן, שגזרו גזירות לבטל את המילה ושאר מצוות, מצד ה\u0003ד\u0004\u0003ין הוא שנגזור על עצמנו שלא לישא אשה ו\u0004לא \u0003להוליד בנים, ונמצא זרעו של אברהם אבינו כלה מאליו\u0004 ולא ייגרם מצב שיהיו ילדים שאינם נימולים,","\u0003אלא הנח להם לישראל\u0004 ואל תגזור גזירה שאינם יכולים לעמוד בה. \u0003מוטב שיהיו שוגגין\u0004 ולא יחשבו שיש בדבר הזה איסור, \u0003ואל יהיו מזידין\u0004",""],["\u0003המוכר את הבית\u0004 סתם ולא פרט אלו חלקים ממנו הוא מוכר — \u0003לא מכר\u0004 בכלל זה את \u0003יציע\u0004 הבית שנמצא בצידו או מעליו, \u0003ואף על פי שהיא\u0004 היציע \u0003פתוחה לתוכו\u0004 של הבית. \u0003ו\u0004כן \u0003לא\u0004 מכר בכלל הבית \u0003את החדר שלפנים הימנו\u0004 (ממנו) שיש לו שימוש לעצמו שאינו כשימוש הבית, \u0003ולא\u0004 מכר \u0003את הגג בזמן שיש לו\u0004 לגג \u0003מעקה גבוה עשרה טפחים,\u0004 שגג כזה נחשב לעצמו ואינו בכלל מכירת הבית. \u0003ר' יהודה אומר:\u0004 אף \u0003אם יש לו\u0004 למעקה \u0003צורת פתח,\u0004 כלומר, עמודים שעליהם מונחת קורה וכיוצא בה, הרי \u0003אף על פי שאינו גבוה עשרה טפחים\u0004 — הגג \u0003אינו מכור.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יציע\"? הכא תרגימו\u0004 \u0005[כאן תרגמו,\u0006 הסבירו\u0005]:\u0006 \u0003אפתא,\u0004 מעין עלייה קטנה הבנויה בתוך הבית. \u0003רב יוסף אמר: בדקא חלילה,\u0004 מבנה הצמוד לבית. ומעירים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003אפתא לא מזדבנא\u0004 \u0005[אינה נמכרת],\u0006 \u0003כל שכן\u0004 ש\u0003בדקא חלילה לא מזדבנא\u0004 \u0005[נמכרת],\u0006 משום שבוודאי אינה חלק מהבנין, אבל \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שיציע הוא \u0003בדקא חלילה\u0004 יש לדייק: דווקא היא איננה נמכרת, \u0003אבל אפתא מזדבנא\u0004 \u0005[נמכרת].\u0006","\u0003תאני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף, שלש שמות יש לו\u0004 במקרא למבנה הקטן שצמוד לבית: \u0003\"יציע\", \"צלע\", \"תא\". \"יציע\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתיאור המקדש שבנה שלמה: \u0003\"היציע התחתנה חמש באמה רחבה\"\u0004 (מלכים א' ו, ו). \u0003\"צלע\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתיאור המקדש שביחזקאל: \u0003\"והצלעות צלע אל צלע שלש ושלשים פעמים\"\u0004 (יחזקאל מא, ו). \u0003\"תא\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והתא קנה אחד ארך וקנה אחד רחב ובין התאים חמש אמות\"\u0004 (יחזקאל מ, ז). \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ראיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 ששנינו במשנה: \u0003כותל ההיכל שש\u0004 אמות, \u0003והתא שש\u0004 אמות, \u0003כותל התא חמש\u0004 אמות. ואם כן התא עומד לעצמו לצד כותל ההיכל.","ולענין מה ששנינו במשנה שיציע אינו נמכר בכלל הבית, \u0003אמר מר זוטרא\u0004 הלכה: \u0003והוא, דהוי\u0004 \u0005[ש\u0006היציע \u0005הינו]\u0006 בגודל של \u0003ארבע אמות\u0004 על ארבע אמות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למר זוטרא: לדידך דאמרת\u0004 \u0005[ל\u0006שיטה \u0005שלך שאתה אומר]\u0006 \u0003עד דהוי\u0004 \u0005[שהוא]\u0006 \u0003ארבע אמות\u0004 על ארבע אמות, \u0003אלא מעתה, גבי\u0004 \u0005[אצל]\u0006 \u0003בור דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 שהמוכר את הבית לא מכר בעל הבית \u0003לא את הבור ולא את הדות\u0004 (בור בנוי מאבנים), \u0003אף על פי שכתב לו\u0004 שהוא מוכר לו \u0003עומקא ורומא\u0004 \u0005[עומק ורום]\u0006 הבית, \u0003הכי נמי אי הוו\u0004 \u0005[כך גם כן, אם הם]\u0006 בני \u0003ארבע אמות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא?\u0004 והרי בור בוודאי אינו גדול כל כך!","אמר לו: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]\u0006 בין בור ליציע?! \u0003התם הא תשמישתא לחוד והא תשמישתא לחוד\u0004 \u0005[שם,\u0006 בבור\u0005, זה\u0006 הבור \u0005שימוש לחוד וזה\u0006 הבית \u0005שימוש לחוד],\u0006 שהרי שימושו של בור לצורך מים, ולא לדירה. \u0003הכא אידי ואידי חדא תשמישתא היא\u0004 \u0005[כאן,\u0006 ביציע, \u0005זה וזה\u0006 יציע ובית \u0005תשמיש אחד הוא],\u0006 ולפיכך \u0003אי הוי\u0004 \u0005[אם הינו]\u0006 \u0003ארבע אמות\u0004 — הריהו \u0003חשיב\u0004 \u0005[חשוב\u0006 לעצמו\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא חשיב\u0004 \u0005[חשוב]\u0006 והוא כחלק מהבית.","שנינו במשנה שהמוכר את הבית בסתם, בלא פירוט, אינו מוכר את היציע \u0003ולא את החדר שלפנים הימנו.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יציע לא מיזדבן\u0004 \u0005[אינו נמכר]\u0006 יחד עם הבית, \u0003חדר מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאינו נמכר?"],["ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לומר ש\u0003אף על גב\u0004 ש\u0003מצר,\u0004 הגדיר, \u0003ליה\u0004 \u0005[לו\u0006 לקונה\u0005]\u0006 בשטר המכר את \u0003מצרי אבראי\u0004 \u0005[המצרים,\u0006 הגבולות \u0005החיצוניים\u0006 של הבית\u0005]\u0006 באיזה בתים הוא גובל מצדדיו השונים, עם זאת אין אומרים שנתכוון לכלול גם את החדר בכלל מכירת הבית.","\u0003כ\u0004דברי \u0003רב נחמן\u0004 בנושא דומה, ש\u0003אמר רב נחמן אמר רבה בר אבוה: המוכר בית לחבירו בבירה גדולה,\u0004 מבנה גדול שיש בתוכו בתים רבים, \u0003אף על פי שמצר לו מצרים החיצונים\u0004 של הבנין הגדול כולו — \u0003מצרים הרחיב לו,\u0004 כלומר, לא הגדיר את מה שעומד למכור בגבולות המדוייקים שלו, אלא בהגדרה רחבה יותר של מקומו הכללי, אבל לא נתכוון למכור לו כל מה שבתוך המצרים הללו.","ולעצם דברי רב נחמן תוהים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דקרו ליה\u0004 \u0005[אם תאמר\u0006 שמדובר במקום \u0005שקוראים לו]\u0006 \u0003לבית \"בית\", ולבירה\u0004 קוראים \u0003\"בירה\",\u0004 ומבחינים תמיד בין מונחים אלה, אם כן \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שלא נתכוון לכל הבירה, ורק מצרים הרחיב לו, כי \u0003בית זבין ליה\u0004 \u0005[מכר לו],\u0006 \u0003בירה לא זבין ליה\u0004 \u0005[מכר לו]!\u0006 \u0003אלא\u0004 תאמר שמדובר במקום שבו \u0003לבירה נמי קרו\u0004 \u0005[גם כן קוראים]\u0006 \u0003לה בית,\u0004 אם כן \u0003כוליה זבין ליה\u0004 \u0005[\u0006את \u0005הכל מכר לו]!\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקום \u0003דרובא קרו ליה\u0004 \u0005[שרוב\u0006 האנשים \u0005קוראים לו]\u0006 \u0003לבית \"בית\",\u0004 ו\u0003לבירה\u0004 — \u0003\"בירה\", ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 אחרים שאינם מדייקים ו\u0003לבירה קרו ליה\u0004 \u0005[קוראים לה]\u0006 \u0003\"בית\". מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי את הבירה \u0003כוליה\u0004 \u0005[כולה]\u0006 \u0003זבין ליה\u0004 \u0005[מכר לו]\u0006 מתוך שמצר לו מצרים החיצוניים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב נחמן, כי \u0003מדהוה ליה למכתב\u0004 \u0005[מתוך שהיה לו לכתוב]:\u0006 \u0003\"ולא שיירית בזביני אלין\u0004 \u0005[שיירתי במכירתי זו]\u0006 \u0003כלום\"\u0004 \u0003ולא כתב\u0004 דברים אלה, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003שיורי\u0004 \u0005[שיור]\u0006 \u0003שייר\u0004 דברים לעצמו, ולא מכר את כל הנמצא בתוך מצרים אלה.","\u0003ו\u0004בדומה לכך \u0003אמר רב נחמן אמר רבה בר אבוה: המוכר שדה\u0004 אחד \u0003לחבירו ב\u0004תוך \u0003בקעה גדולה, אף על פי שמצר לו מצרים החיצונים\u0004 של הבקעה — \u0003מצרים הרחיב לו,\u0004 ולא מכר לו את כל הבקעה.","ושוב שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דקרו ליה\u0004 \u0005[אם תאמר\u0006 במקום \u0005שקוראים לו]\u0006 \u0003לשדה \"שדה\", ולבקעה\u0004 — \u0003\"בקעה\",\u0004 ומבחינים בין המושגים, במקרה זה \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שכן \u0003שדה זבין ליה\u0004 \u0005[מכר לו],\u0006 \u0003בקעה לא זבין ליה\u0004 \u0005[מכר לו]!\u0006 \u0003ואלא\u0004 תאמר שמדובר במקום ש\u0003לבקעה נמי קרו\u0004 \u0005[גם כן קוראים]\u0006 \u0003לה \"שדה\",\u0004 הרי אז — את \u0003כולה זבין ליה\u0004 \u0005[מכר לו]!\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקום \u0003דאיכא\u0004 \u0005[שיש]\u0006 אנשים ש\u0003לשדה קרו ליה\u0004 \u0005[קוראים לו]\u0006 \u0003\"שדה\", ולבקעה\u0004 — \u0003\"בקעה\", ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 כאלה ש\u0003לבקעה קרו\u0004 \u0005[קוראים]\u0006 \u0003לה \"שדה\", מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כוליה זבין ליה\u0004 \u0005[\u0006את \u0005הכל מכר לו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003מדהוה ליה למכתב ליה\u0004 \u0005[מתוך שהיה לו לכתוב לו]:\u0006 \u0003\"לא שיירית בזביני אלין קדמי\u0004 \u0005[השארתי במכירתי זו לפני]\u0006 \u0003כלום\"\u0004 \u0003ולא כתב ליה\u0004 \u0005[לו]\u0006 דברים אלה, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003שיורי\u0004 \u0005[שיור]\u0006 \u0003שייר\u0004 לעצמו.","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 ההלכה להיאמר בשני המקרים: \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003בית\u0004 שאין כל הבירה בכלל אף שמצר לו מצרים חיצוניים, הייתי אומר שטעם הדבר הוא \u0003משום דהא תשמישתא לחוד והא תשמישתא לחוד\u0004 \u0005[שזה שימוש לחוד וזה שימוש לחוד],\u0006 ומן הסתם כשכתב המוכר בשטר המכר בית התכוון לבית דווקא ולא לבירה, ואין מצרי הבירה אלא הגדרה כללית של מקום הבית. \u0003אבל בקעה\u0004 ש\u0003כולה חדא תשמישתא היא\u0004 \u0005[שימוש אחד הוא]\u0006 \u0003אימא כוליה זבין ליה\u0004 \u0005[אמור\u0006 שאת \u0005הכל מכר לו].\u0006","ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק \u0003בקעה,\u0004 היינו אומרים שדין זה נאמר רק שם, \u0003משום\u0004 ש\u0003לא הוה ליה למימצר ליה\u0004 \u0005[היה לו\u0006 באפשרותו \u0005לתחום לו]\u0006 מצרים מדוייקים של השדה, כיון שכל השדות דומים וכולם שלו, ולכן כתב לו את התחום הכללי שבתוכו מצוי שדה זה. \u0003אבל בית, דהוה ליה למימצר ליה\u0004 \u0005[שהיה לו לתחום לו],\u0006 שהרי בבנין גדול יש לבתים או חדרים שונים הגדרות משלהם ( מטבח, מחסן, בית שפלוני דר בו וכיוצא בזה) ויכול היה לתחום על ידם את הבית שרצה למכור לו, \u0003ו\u0004מכל מקום \u0003לא מצר ליה\u0004 \u0005[תחם,\u0006 הגדיר \u0005לו\u0006 תחומים\u0005],\u0006 שמא \u0003כוליה זבין ליה\u0004 \u0005[\u0006את \u0005הכל מכר לו],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","ומעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב מרי בריה\u0004 \u0005[בנה]\u0006 של \u0003בת שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: האי מאן דמזבני ליה מידי לחבריה\u0004 \u0005[מי שמוכר לו דבר לחבירו],\u0006 \u0003צריך למכתב ליה\u0004 \u0005[לכתוב לו]\u0006 בשטר המכר נוסח כזה: \u0003\"לא שיירית בזביני אלין קדמי\u0004 \u0005[השארתי במכירתי זו לפני]\u0006 \u0003כלום\",\u0004 \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 היא\u0005]?\u0006 \u0003כ\u0004דעת \u0003רב נחמן\u0004 ש\u0003אמר\u0004 בשם \u0003רבה בר אבוה\u0004 שאמרנו לעיל, שאף שהמוכר מגדיר גבולות מסויימים — אין זה כולל כל מה שבתוכם, ועל ידי שימוש בלשון זו מסיר ספיקות העלולים להביא לידי סכסוך.","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה\u0004 \u0003לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003\"ארעא דבי חייא מזבננא\u0004 \u0005[\u0006את \u0005הקרקע של בית חייא אני מוכר]\u0006 \u0003לך\". הואי ליה תרתי ארעתא דהוה מתקרין \"דבי חייא\"\u0004 \u0005[היו לו שתי קרקעות שהיו נקראות \"של בית חייא\"],\u0006 והיו מתדיינים אם מכר לו שתיהן או רק אחת מהן. \u0003אמר רב אשי: חדא\u0004 \u0005[\u0006קרקע \u0005אחת]\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תרתי\u0004 \u0005[שתים]\u0006 \u0003לא אמר ליה\u0004 \u0005[לו].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"ארעתא\" סתמא\u0004 \u0005[\"קרקעות\" סתם]\u0006 — \u0003מיעוט ארעתא\u0004 \u0005[קרקעות]\u0006 \u0003שתים\u0004 וצריך לתת לו רק שני שדות מאחוזה זו, אף אם יש בה שדות רבים. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"כל ארעתא\u0004 \u0005[הקרקעות]\u0006 אני מוכר לך \u0003\"\u0004— הכוונה היא \u0003כל ארעתא דאית ליה\u0004 \u0005[כל הקרקעות שיש לו],\u0006 \u0003לבר מבוסתני ופרדיסי\u0004 \u0005[חוץ ממטעים וכרמים].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"זיהרא\",\u0004 כלומר, נכסי מקרקעין — \u0003אפילו בי בוסתני ופרדיסי\u0004 \u0005[בית המטעים והכרמים]\u0006 מכר לו, \u0003לבר מבתי ועבדי\u0004 \u0005[חוץ מבתים ועבדים]\u0006 שאינם נכללים בלשון \"זיהרא\"."]]};
